-- FLL-TP-RHIZOM-2023 · engineer hints on every field, equation and compliance requirement (hint wave 2026-10-05).
-- Each description now carries a German hint and an English part after the marker "[EN] " (src/lib/eval/hint-text.ts; the form
-- renders the part of the page locale; the approval refusal prints the whole text as "Hinweis" for a block gate without its inputs).
-- Content authored from the printed guideline pages (rendered PDF read in the authoring session; the authoring JSON in the vault
-- carries a source string with the printed page per hint); every number / limit / clause in a hint is traceable to those pages.
-- SAFETY: text only (fields.description, equations.description, compliance_requirements.description); no field, equation, gate,
-- value or severity changes. The pre-block descriptions (encoder notes) are restored by the rollback and kept in the inventory JSON.
-- STAGED — not applied. Apply: node scripts/apply-migration.mjs scripts/migrations/20261005170000_fll_tp_rhizom_hints.sql
-- Rollback: scripts/migrations/rollback-20261005170000_fll_tp_rhizom_hints.sql
BEGIN;
UPDATE fields x SET description = 'Bestätigung, dass der Bambus-Hinweis im Prüfbericht bzw. in der Produktdokumentation steht: Das Prüfergebnis ist nicht auf Pflanzen mit sehr starkem Rhizomwachstum (z. B. Bambus-Arten) übertragbar; bei solchen Pflanzen sind über den befundenen Ein- und Durchdringungsschutz hinausgehende bauliche Vorkehrungen und besondere Pflegemaßnahmen vorzusehen (§ 2, S. 8). Tor REQ-02 sperrt die Freigabe des Blatts, bis der Haken gesetzt ist.
[EN] Attest that the bamboo note is included in the test report or the product documentation: the result cannot be transferred to plants with very strong rhizome growth (e.g. bamboo species); where such plants are used, structural precautions beyond the proven resistance and special maintenance measures must be provided (§ 2, p. 8). Gate REQ-02 blocks approval of this sheet until the box is ticked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-01' AND x.symbol = 'attest_flltp_rhz_01_req_02';
UPDATE fields x SET description = 'Vollständige Kontaktdaten des Auftraggebers der Prüfung (Anschrift, Ansprechperson, Telefon/E-Mail). Sie erscheinen auf dem Deckblatt des Prüfberichts („Name und Kontaktdaten des Auftraggebers“, Musterbericht S. 25); der Bericht wird in doppelter Ausführung erstellt, ein Exemplar für den Auftraggeber (§ 9, S. 22). Wird nach FLLTP-RHZ-19 übernommen; keine fachliche Prüfung.
[EN] Full contact details of the client commissioning the test (address, contact person, phone/e-mail). They appear on the cover of the test report (''Name und Kontaktdaten des Auftraggebers'', sample report p. 25); the report is issued in duplicate, one copy for the client (§ 9, p. 22). Carried into FLLTP-RHZ-19; no technical check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-01' AND x.symbol = 'auftraggeber_kontakt';
UPDATE fields x SET description = 'Name des Auftraggebers (Firma oder Person), der die Prüfung in Auftrag gibt. Der Auftraggeber ist für Beschaffung und Einbau der Trennlage und der zu prüfenden Abdichtung, die Abgabe einer Materialprobe und die Angaben zur Abdichtung zuständig (§ 11, S. 24); die Zuständigkeiten und die Kostenübernahme werden im Vertrag mit dem Prüfinstitut geregelt. Der Name steht auf dem Deckblatt des Berichts (S. 25) und wird nach FLLTP-RHZ-19 übernommen.
[EN] Name of the client (company or person) commissioning the test. The client is responsible for procuring and installing the separation layer and the sealing under test, for supplying a material sample and for the product data (§ 11, p. 24); responsibilities and costs are fixed in the contract with the test institute. The name appears on the report cover (p. 25) and is carried into FLLTP-RHZ-19.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-01' AND x.symbol = 'auftraggeber_name';
UPDATE fields x SET description = 'Eindeutige Kennung des Prüfberichts, die das Prüfinstitut nach seinem eigenen System vergibt. Sie wird nach FLLTP-RHZ-19 übernommen und erlaubt die eindeutige Bezugnahme auf diesen Bericht bei einer späteren Korrektur oder Verlängerung. Die Richtlinie schreibt kein Nummernformat vor; keine Prüfung.
[EN] Unique identifier of the test report, assigned by the test institute under its own numbering system. Carried into FLLTP-RHZ-19; it allows unambiguous reference to this report in a later correction or extension. The guideline prescribes no number format; no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-01' AND x.symbol = 'pruefbericht_nr';
UPDATE fields x SET description = 'Name und Anschrift des Prüfinstituts, das die Prüfung durchführt. Das Prüfinstitut stellt die Versuchsfläche, beschafft und baut Widerlager, Standrohre und Vegetationstragschicht ein, beschafft und pflegt die Testpflanzen, wertet aus und erstellt den Prüfbericht (§ 11, S. 24); es lagert die Rückstellproben (§ 6, S. 16). Erscheint im Berichtskopf (S. 25) und wird nach FLLTP-RHZ-19 und FLLTP-RHZ-21 übernommen.
[EN] Name and address of the test institute carrying out the test. The institute provides the test area, procures and installs abutment, standpipes and substrate, procures and tends the test plants, evaluates and writes the test report (§ 11, p. 24); it stores the retained samples (§ 6, p. 16). Appears in the report header (p. 25) and is carried into FLLTP-RHZ-19 and FLLTP-RHZ-21.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-01' AND x.symbol = 'pruefinstitut_name';
UPDATE fields x SET description = 'Datum, an dem die Prüfung endet: planmäßig nach der 2-jährigen Prüfdauer mit der Endauswertung nach 24 Monaten (§ 4, S. 12; § 3.7, S. 10) oder früher bei vorzeitigem Abbruch, etwa bei erkennbaren Rhizomdurchdringungen oder unzureichender Wuchsleistung (§ 3.12, S. 11). Zu Beginn das geplante Datum eintragen, nach Prüfende auf das tatsächliche Datum korrigieren; wird nach FLLTP-RHZ-19 übernommen.
[EN] Date on which the test ends: as planned after the 2-year test duration with the final evaluation after 24 months (§ 4, p. 12; § 3.7, p. 10), or earlier if the test is stopped, e.g. on visible rhizome penetration or insufficient plant growth (§ 3.12, p. 11). Enter the planned date at the start and correct it to the actual date after the test; carried into FLLTP-RHZ-19.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-01' AND x.symbol = 'pruefung_enddatum';
UPDATE fields x SET description = 'Datum, ab dem die 2-jährige Prüfung im Gewächshaus zählt (§ 4, S. 12); im Wizard gilt der Abschluss von Einbau und Bepflanzung als Start. Von hier aus rechnen die Zwischenauswertungen nach 6, 12 und 18 Monaten und die Endauswertung nach 24 Monaten (§ 3.7, S. 10) sowie die Frist von drei Monaten, in der abgestorbene Pflanzen ersetzt werden dürfen (§ 7.3, S. 20). Die Blätter FLLTP-RHZ-13 bis 16 beziehen sich auf dieses Datum.
[EN] Date from which the 2-year greenhouse test counts (§ 4, p. 12); in the Wizard the completion of installation and planting is taken as the start. The interim evaluations after 6, 12 and 18 months and the final evaluation after 24 months (§ 3.7, p. 10) as well as the three-month window for replacing dead plants (§ 7.3, p. 20) are counted from here. Sheets FLLTP-RHZ-13 to 16 refer to this date.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-01' AND x.symbol = 'pruefung_startdatum';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn auf FLLTP-RHZ-02 eine Abdichtungsart der Liste des § 2 gewählt ist (Bitumenbahn, Kunststoff- oder Elastomerbahn, Flüssigabdichtung, Gussasphalt, GUP-Beschichtung) und auf FLLTP-RHZ-03 „Einzelprodukt (kein System)“ mit Ja bestätigt ist; ohne beide Eingaben bleibt das Tor rot. Grund: Das Verfahren prüft einzelne Produkte für Abdichtungsschichten nach Abschnitt 10.4 der FLL-Gewässerabdichtungsrichtlinien einschließlich ihrer Fügetechnik; die Prüfung eines Abdichtungssystems aus mehreren Funktionsschichten oder mit zusätzlicher Kaschierung ist nicht zulässig (§ 2, S. 8).
[EN] Passes when a sealing type from the § 2 list is selected on FLLTP-RHZ-02 (bitumen sheet, plastic or elastomer sheet, liquid sealing, mastic asphalt, GUP coating) and ''Single product (not a system)'' is confirmed with Yes on FLLTP-RHZ-03; without both entries the gate stays red. Reason: the method tests single products for sealing layers per section 10.4 of the FLL water-body sealing guidelines including their joining technique; testing a sealing system made of several functional layers or with an additional lamination is not permitted (§ 2, p. 8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-01' AND x.code = 'REQ-01';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn der Haken „Nachweis: § 2“ gesetzt ist. Damit bestätigen Sie, dass im Prüfbericht bzw. in der Produktdokumentation steht: Das Ergebnis ist nicht auf Pflanzen mit sehr starkem Rhizomwachstum (z. B. Bambus-Arten) übertragbar; bei solchen Pflanzen sind über den befundenen Ein- und Durchdringungsschutz hinausgehende bauliche Vorkehrungen und besondere Pflegemaßnahmen vorzusehen (§ 2, S. 8). Ohne Haken wird die Freigabe verweigert.
[EN] Passes when the box ''Nachweis: § 2'' is ticked. You thereby confirm that the test report or product documentation states: the result cannot be transferred to plants with very strong rhizome growth (e.g. bamboo species); where such plants are used, structural precautions beyond the proven resistance and special maintenance measures must be provided (§ 2, p. 8). Without the tick, approval is refused.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-01' AND x.code = 'REQ-02';
UPDATE fields x SET description = 'Art der zu prüfenden Abdichtung nach § 2 (S. 8): Bitumenbahn, Kunststoffbahn oder Elastomerbahn (bahnenförmig, am Untersuchungsort gefügt) bzw. Flüssigabdichtung, Gussasphalt oder GUP-Beschichtung (nicht bahnenförmig, in zwei Arbeitsschritten aufgetragen). Aus Produktbezeichnung und Produktdatenblatt des Herstellers entnehmen (§ 6, S. 16). Die Wahl speist Tor REQ-01 (FLLTP-RHZ-01) und bestimmt zusammen mit „Bahnenartig?“ die Naht- bzw. Arbeitsfugen-Anforderungen beim Einbau (§ 7.1, S. 17) auf FLLTP-RHZ-09.
[EN] Type of sealing under test per § 2 (p. 8): bitumen sheet, plastic sheet or elastomer sheet (sheet-type, joined on site) or liquid sealing, mastic asphalt or GUP coating (non-sheet, applied in two work steps). Take it from the product designation and the manufacturer''s data sheet (§ 6, p. 16). The choice feeds gate REQ-01 (FLLTP-RHZ-01) and, together with ''Sheet-type?'', determines the seam or work-joint requirements for installation (§ 7.1, p. 17) on FLLTP-RHZ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'abdichtungsart';
UPDATE fields x SET description = 'Alle Fügetechniken, mit denen die Prüfmuster am Untersuchungsort verbunden werden (z. B. Quellschweißung, Warmgasschweißung), samt Fügemittel und Art der Nahtversiegelung nach den Herstellerangaben (§ 6, S. 16). Verschiedene Techniken dürfen kombiniert werden, wenn sie ausnahmslos stoffhomogene Nahtverbindungen ergeben; Kombinationen aus klebefreien Verbindungen und Klebemasse oder aus zwei verschiedenen Klebemassen gelten nicht als gleichwertig (§ 3.8, S. 10). Das Ergebnis ist an die hier genannten, gleichwertigen Fügetechniken gebunden (§ 2, S. 8; § 9, S. 22).
[EN] All joining techniques used to join the specimens on site (e.g. solvent welding, hot-gas welding), with the joining agent and type of seam sealing as given by the manufacturer (§ 6, p. 16). Different techniques may be combined if all of them produce material-homogeneous seams; combinations of adhesive-free joints with adhesive compounds, or of two different adhesive compounds, are not considered equivalent (§ 3.8, p. 10). The result is bound to the equivalent joining techniques named here (§ 2, p. 8; § 9, p. 22).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'fuegetechniken_angewandt';
UPDATE fields x SET description = 'Nur bei Beschichtungen (Flüssigabdichtung, Gussasphalt, GUP-Beschichtung): „Ja“, wenn aus versuchstechnischen Gründen unter der Beschichtung eine gesonderte Lage eingebaut wird. Das ist zulässig, sofern der Hersteller eindeutig erklärt, dass die Rhizomfestigkeit einzig durch die zuoberst aufgetragene Beschichtung bewirkt wird (§ 2, S. 8); diese Erklärung zu den Produktunterlagen nehmen. Bei Bahnen leer lassen oder „Nein“.
[EN] Coatings only (liquid sealing, mastic asphalt, GUP coating): ''Yes'' if, for test-technical reasons, a separate layer is installed beneath the coating. This is permitted provided the manufacturer declares unambiguously that the rhizome resistance is produced solely by the topmost applied coating (§ 2, p. 8); file that declaration with the product documents. For sheets leave empty or ''No''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'gesonderte_lage_eingebaut';
UPDATE fields x SET description = 'Name und Anschrift des Herstellers des Produkts. Der Hersteller liefert zu Beginn der Untersuchung die Produktangaben und hinterlegt ein Produktdatenblatt beim Prüfinstitut (§ 6, S. 16); seine Kennzeichnung oder sein Markenzeichen kann im Bericht als eindeutige Kennzeichnung des Musters angegeben werden (§ 10, S. 23). Wird nach FLLTP-RHZ-19 und FLLTP-RHZ-20 übernommen.
[EN] Name and address of the product''s manufacturer. The manufacturer supplies the product data at the start of the investigation and lodges a product data sheet with the test institute (§ 6, p. 16); its marking or trademark may be given in the report as the unique identification of the sample (§ 10, p. 23). Carried into FLLTP-RHZ-19 and FLLTP-RHZ-20.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'hersteller_name';
UPDATE fields x SET description = '„Ja“ bei bahnenförmigen Abdichtungen (Bitumen-, Kunststoff-, Elastomerbahn): Bahnteile werden zugeschnitten und am Untersuchungsort gefügt; dann gelten die Nahtvorgaben (vier Wand-Eck-, zwei Boden-Eck-, eine T-Naht am 1. Prüfmuster; 2. Prüfmuster um 45° versetzt mit zwei Längsnähten). „Nein“ bei nicht bahnenförmigen Abdichtungen wie Flüssigabdichtung, Gussasphalt oder GUP-Beschichtung: Einbau in zwei Arbeitsschritten mit mittiger Arbeitsunterbrechungsfuge, Zeitabstand mindestens 12 Stunden (§ 7.1, S. 17). Schaltet die Tore REQ-11 und REQ-12 auf FLLTP-RHZ-09.
[EN] ''Yes'' for sheet-type sealings (bitumen, plastic, elastomer sheet): sheet pieces are cut and joined on site; the seam rules then apply (four wall-corner, two floor-corner and one T-seam on the 1st specimen; 2nd specimen rotated 45° with two longitudinal seams). ''No'' for non-sheet sealings such as liquid sealing, mastic asphalt or GUP coating: installed in two work steps with a central work joint, at least 12 hours apart (§ 7.1, p. 17). Switches gates REQ-11 and REQ-12 on FLLTP-RHZ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'ist_bahnenartig';
UPDATE fields x SET description = '„Ja“, wenn das Produkt aus mehreren Schichten besteht, z. B. Bitumenbahn mit Kupferbandeinlage oder Kunststoff-/Elastomerbahn mit Einlage oder Verstärkung (§ 3.9, S. 10; § 6, S. 16). Dann muss der Hersteller zu Prüfbeginn eindeutig festlegen, welche Schicht den Ein- und Durchdringungsschutz übernimmt (Feld „Definition der Schutzschicht“); Tor REQ-04 verlangt diese Angabe. In andere Schichten eingewachsene Rhizome gelten nicht als Rhizomeindringung, solange die Schutzschicht unbeschädigt bleibt, sind aber im Bericht aufzuführen (§ 3.9, S. 10). Gelesen von FLLTP-RHZ-17.
[EN] ''Yes'' if the product consists of several layers, e.g. bitumen sheet with copper-band insert or plastic/elastomer sheet with insert or reinforcement (§ 3.9, p. 10; § 6, p. 16). The manufacturer must then define unambiguously at the start of the test which layer provides the protection against ingress and penetration (field ''Definition of protective layer''); gate REQ-04 requires it. Rhizomes grown into other layers do not count as ingress as long as the protective layer is undamaged, but must be reported (§ 3.9, p. 10). Read by FLLTP-RHZ-17.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'mehrschichtprodukt';
UPDATE fields x SET description = 'Eindeutige Produktbezeichnung (Produktname bzw. Handelsname, Typ, Variante) laut Herstellerangaben und Produktdatenblatt (§ 6, S. 16). Sie steht auf dem Deckblatt des Prüfberichts (S. 25); der Bericht gilt ausschließlich für das untersuchte Produkt, eine Übertragung auf andere Produkte ist nicht statthaft (§ 9, S. 22), und eine Neuausstellung unter geändertem Handelsnamen ohne erneute Prüfung ist nicht zulässig (§ 10, S. 23). Wird in FLLTP-RHZ-09, 17, 18, 19 und 20 weitergeführt.
[EN] Unique product designation (product or trade name, type, variant) as given by the manufacturer and the product data sheet (§ 6, p. 16). It appears on the report cover (p. 25); the report applies exclusively to the tested product, transfer to other products is not admissible (§ 9, p. 22), and re-issuing under a changed trade name without re-testing is not permitted (§ 10, p. 23). Carried into FLLTP-RHZ-09, 17, 18, 19 and 20.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'produktbezeichnung';
UPDATE fields x SET description = 'Nur bei Mehrschichtprodukten: Bezeichnung der Schicht, die den Ein- und Durchdringungsschutz übernimmt, so wie der Hersteller sie zu Prüfbeginn eindeutig festgelegt hat (§ 3.9, S. 10; § 6, S. 16), z. B. aus dem Produktdatenblatt. Tor REQ-04 verlangt die Angabe, sobald „Mehrschichtprodukt?“ = Ja. Die Endbewertung auf FLLTP-RHZ-17 stützt sich darauf: Rhizome in anderen Schichten sind keine Eindringung, wenn diese Schicht nicht beschädigt ist.
[EN] Multilayer products only: name of the layer that provides the protection against ingress and penetration, as defined unambiguously by the manufacturer at the start of the test (§ 3.9, p. 10; § 6, p. 16), e.g. from the product data sheet. Gate REQ-04 requires it once ''Multilayer product?'' = Yes. The final assessment on FLLTP-RHZ-17 relies on it: rhizomes in other layers are not an ingress if this layer is undamaged.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'schutzschicht_definition';
UPDATE fields x SET description = '„Ja“, wenn das Produkt wachstumshemmende Wirkstoffe (Biozide, Hemmstoffe) enthält; der Hersteller muss das zu Prüfungsbeginn eindeutig erklären und die Konzentration angeben (§ 3.9, S. 10; § 6, S. 16). Folge für die Auswertung: bei solchen Produkten gelten bis 5 mm in Fläche, Naht oder Arbeitsunterbrechungsfuge eingewachsene Rhizome nicht als Rhizomeindringung, sind aber im Bericht aufzuführen (§ 3.9, S. 10). Tor REQ-03 verlangt eine ausdrückliche Antwort Ja/Nein; nicht leer lassen. Gelesen von FLLTP-RHZ-17.
[EN] ''Yes'' if the product contains growth-inhibiting substances (biocides, inhibitors); the manufacturer must declare this unambiguously at the start of the test and state the concentration (§ 3.9, p. 10; § 6, p. 16). Consequence for the evaluation: for such products, rhizomes grown up to 5 mm into the surface, seam or work joint do not count as ingress but must be reported (§ 3.9, p. 10). Gate REQ-03 requires an explicit Yes/No; do not leave empty. Read by FLLTP-RHZ-17.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.symbol = 'wachstumshemmende_wirkstoffe';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn „Mit wachstumshemmenden Wirkstoffen?“ ausdrücklich mit Ja oder Nein beantwortet ist; ein leeres Feld sperrt die Freigabe. Grund: Produkte mit hemmenden Wirkstoffen sind vom Hersteller zu Prüfungsbeginn eindeutig als „mit wachstumshemmenden Wirkstoffen versehen“ zu definieren, weil nur dann bis 5 mm eingewachsene Rhizome nicht als Eindringung gewertet werden (§ 3.9, S. 10); § 6 verlangt die Angabe des Zusatzes von Bioziden mit Konzentration (S. 16).
[EN] Passes when ''Contains growth-inhibiting substances?'' is explicitly answered Yes or No; an empty field blocks approval. Reason: products with inhibiting substances must be defined by the manufacturer at the start of the test as ''provided with growth-inhibiting substances'', because only then are rhizomes grown in up to 5 mm not counted as ingress (§ 3.9, p. 10); § 6 requires the addition of biocides to be stated with its concentration (p. 16).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.code = 'REQ-03';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn „Mehrschichtprodukt?“ = Nein ist, oder wenn bei Ja die Schutzschicht im Feld „Definition der Schutzschicht“ benannt ist. Bei Produkten aus mehreren Schichten (z. B. Bitumenbahn mit Kupferbandeinlage, Bahn mit Einlage oder Verstärkung) ist vom Hersteller zu Prüfbeginn eindeutig festzulegen, welche Schicht den Ein- und Durchdringungsschutz übernimmt (§ 6, S. 16; § 3.9, S. 10); ohne diese Festlegung lässt sich am Prüfende nicht bewerten, ob eine Rhizomeindringung vorliegt.
[EN] Passes when ''Multilayer product?'' = No, or when, for Yes, the protective layer is named in ''Definition of protective layer''. For products made of several layers (e.g. bitumen sheet with copper-band insert, sheet with insert or reinforcement) the manufacturer must define unambiguously at the start of the test which layer provides the protection against ingress and penetration (§ 6, p. 16; § 3.9, p. 10); without it, rhizome ingress cannot be assessed at the end of the test.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-02' AND x.code = 'REQ-04';
UPDATE fields x SET description = '„Ja“, wenn ein einzelnes Produkt für die Herstellung von Abdichtungsschichten einschließlich seiner Fügetechnik geprüft wird. Die Prüfung eines Abdichtungssystems — eines aus mehreren Funktionsschichten bestehenden Aufbaus oder einer zusätzlichen Kaschierung der Gewässerabdichtung — ist nicht zulässig (§ 2, S. 8). Eine gesonderte Lage unter einer Beschichtung ist kein System, wenn der Hersteller erklärt, dass allein die oberste Beschichtung die Rhizomfestigkeit bewirkt (§ 2, S. 8; Feld auf FLLTP-RHZ-02). Tor REQ-01 auf FLLTP-RHZ-01 liest dieses Feld.
[EN] ''Yes'' if a single product for producing sealing layers, including its joining technique, is tested. Testing a sealing system — a build-up of several functional layers or an additional lamination of the sealing — is not permitted (§ 2, p. 8). A separate layer beneath a coating is not a system if the manufacturer declares that the topmost coating alone produces the rhizome resistance (§ 2, p. 8; field on FLLTP-RHZ-02). Gate REQ-01 on FLLTP-RHZ-01 reads this field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'scope_einzelprodukt_bestaetigt';
UPDATE fields x SET description = 'Anwendungsbereich des Produkts laut Hersteller — eine der Angaben, die zu Beginn der Untersuchung einzufordern sind (§ 6, S. 16). Das Verfahren gilt für Abdichtungsschichten nach Abschnitt 10.4 der FLL-Gewässerabdichtungsrichtlinien für alle Ausbildungsformen von Gewässern im Garten-, Landschafts- und Sportplatzbau (§ 2, S. 8); bei intensiver Beanspruchung durch Bepflanzung (z. B. Pflanzenkläranlagen, Aufbereitungsbereiche von Schwimmteichen) ist diese Prüfung erforderlich (§ 1, S. 7). Freitext, keine Prüfung.
[EN] Application range of the product as stated by the manufacturer — one of the data to be requested at the start of the investigation (§ 6, p. 16). The method applies to sealing layers per section 10.4 of the FLL water-body sealing guidelines for all forms of water bodies in garden, landscape and sports-ground construction (§ 2, p. 8); for intensive planting loads (e.g. constructed wetlands, regeneration zones of swimming ponds) this test is required (§ 1, p. 7). Free text, no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'scope_anwendungsbereich';
UPDATE fields x SET description = 'Abschließende Bestätigung der prüfenden Person, dass das Produkt in den Geltungsbereich fällt: eine Abdichtung der in § 2 genannten Art, Einzelprodukt mit Fügetechnik, kein System (S. 8). Nicht erforderlich ist das Verfahren für Werkstoffe, die aufgrund ihrer Eigenschaften als wurzel- und rhizomfest gelten (z. B. Stahl, Beton, PEHD); Abdichtungen, die nicht nach dem FLL-Verfahren prüfbar sind (z. B. mineralische), sind bei Bedarf gesondert nachzuweisen (§ 1, S. 7). Dokumentationsfeld; kein Tor liest es.
[EN] Final confirmation by the examiner that the product falls within the scope: a sealing of a type named in § 2, a single product with its joining technique, not a system (p. 8). The method is not required for materials that count as root- and rhizome-resistant by their material properties (e.g. steel, concrete, PEHD); sealings that cannot be tested by the FLL method (e.g. mineral sealings) must be verified separately where needed (§ 1, p. 7). Documentation field; no gate reads it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'scope_geltung_validiert';
UPDATE fields x SET description = 'Name der Person, die die Geltungsbereichsprüfung durchgeführt hat (beim Prüfinstitut oder Auftraggeber). Reine Dokumentation der Verantwortung; keine Prüfung.
[EN] Name of the person who carried out the scope check (at the test institute or the client). Documentation of responsibility only; no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'scope_pruefer_name';
UPDATE fields x SET description = 'Datum, an dem die Geltungsbereichsprüfung durchgeführt wurde. Reine Dokumentation; keine Prüfung.
[EN] Date on which the scope check was carried out. Documentation only; no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-03' AND x.symbol = 'scope_pruefung_datum';
UPDATE fields x SET description = 'Stellfläche je Gefäß im Gewächshaus einschließlich des allseitigen Mindestabstands von 0,4 m zwischen den Gefäßen (§ 7.1, S. 18). Für das Mindestgefäß 800 × 800 mm liegt der Bedarf je nach Anordnung bei rund 1,5 bis 2 m² (§ 5.1, S. 13); für 8 Prüf- und 3 Kontrollgefäße entsprechend das Elffache. Aus dem Aufstellplan ermitteln; Planungsangabe, kein Tor.
[EN] Floor area per vessel in the greenhouse including the 0.4 m minimum clearance on all sides between vessels (§ 7.1, p. 18). For the minimum vessel 800 × 800 mm the need is roughly 1.5 to 2 m² depending on the arrangement (§ 5.1, p. 13); eleven times that for 8 test and 3 control vessels. Take it from the layout plan; planning value, no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-04' AND x.symbol = 'flaechenbedarf_pro_gefaess_m2';
UPDATE fields x SET description = 'Kennung des Gewächshauses, in dem die Prüfung läuft. Es muss mit einer regelbaren Heizung und Lüftung ausgestattet sein; die natürlichen Lichtverhältnisse im mitteleuropäischen Raum reichen aus, Schattierung im Sommer oder künstliche Belichtung im Winter sind nicht erforderlich (§ 5.1, S. 13). Das Bereitstellen der Versuchsfläche ist Aufgabe des Prüfinstituts (§ 11, S. 24). Freitext, kein Tor.
[EN] Identifier of the greenhouse in which the test runs. It must have controllable heating and ventilation; natural light in the Central European region is sufficient, summer shading or artificial winter lighting is not required (§ 5.1, p. 13). Providing the test area is the test institute''s task (§ 11, p. 24). Free text, no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-04' AND x.symbol = 'gewaechshaus_id';
UPDATE fields x SET description = 'Innentemperatur, ab der die Lüftung einsetzt (Sollwert der Lüftungsregelung des Gewächshauses). Vorgabe: ab einer Innentemperatur von (22 ±3) °C ist zu lüften, also ein Wert zwischen 19 und 25 °C (§ 5.1, S. 13). Tor REQ-05 prüft diesen Bereich.
[EN] Indoor temperature at which ventilation starts (set point of the greenhouse ventilation control). Requirement: ventilate from an indoor temperature of (22 ±3) °C, i.e. a value between 19 and 25 °C (§ 5.1, p. 13). Gate REQ-05 checks this range.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-04' AND x.symbol = 'temp_lueftung_schwelle_C';
UPDATE fields x SET description = 'Obergrenze der Innentemperatur, die Regelung und Überwachung einhalten. Eine anhaltende Innentemperatur über 35 °C ist zu vermeiden (§ 5.1, S. 13); Tor REQ-05 verlangt daher einen Wert von höchstens 35 °C. Aus der Einstellung der Gewächshaussteuerung übernehmen.
[EN] Upper limit of the indoor temperature maintained by the control and monitoring. A sustained indoor temperature above 35 °C must be avoided (§ 5.1, p. 13); gate REQ-05 therefore requires a value of at most 35 °C. Take it from the greenhouse control settings.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-04' AND x.symbol = 'temp_max_C';
UPDATE fields x SET description = 'Heizungssollwert der Innentemperatur in der Nacht. Vorgabe (16 ±3) °C, also 13 bis 19 °C (§ 5.1, S. 13); Tor REQ-05 prüft den Bereich. Aus der Einstellung der Gewächshaussteuerung übernehmen.
[EN] Heating set point of the indoor temperature at night. Requirement (16 ±3) °C, i.e. 13 to 19 °C (§ 5.1, p. 13); gate REQ-05 checks the range. Take it from the greenhouse control settings.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-04' AND x.symbol = 'temp_nachts_C';
UPDATE fields x SET description = 'Heizungssollwert der Innentemperatur tagsüber. Vorgabe (18 ±3) °C, also 15 bis 21 °C (§ 5.1, S. 13); Tor REQ-05 prüft den Bereich. Aus der Einstellung der Gewächshaussteuerung übernehmen.
[EN] Heating set point of the indoor temperature during the day. Requirement (18 ±3) °C, i.e. 15 to 21 °C (§ 5.1, p. 13); gate REQ-05 checks the range. Take it from the greenhouse control settings.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-04' AND x.symbol = 'temp_tagsueber_C';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn alle vier Temperaturen in den Bereichen des § 5.1 liegen: tagsüber (18 ±3) °C = 15 bis 21 °C, nachts (16 ±3) °C = 13 bis 19 °C, Lüftungsschwelle (22 ±3) °C = 19 bis 25 °C, Obergrenze höchstens 35 °C, weil eine anhaltende Innentemperatur > 35 °C zu vermeiden ist (S. 13). Tragen Sie die Sollwerte der Gewächshaussteuerung in alle vier Felder ein; fehlt ein Wert, bleibt das Tor rot. Die Vorgaben sichern bei natürlichem Licht ein günstiges Wachstum der Testpflanzen im gesamten Jahresgang (§ 5.1, S. 13).
[EN] Passes when all four temperatures lie within the § 5.1 ranges: daytime (18 ±3) °C = 15 to 21 °C, night (16 ±3) °C = 13 to 19 °C, ventilation threshold (22 ±3) °C = 19 to 25 °C, upper limit at most 35 °C because a sustained indoor temperature > 35 °C must be avoided (p. 13). Enter the greenhouse control set points in all four fields; a missing value keeps the gate red. These settings ensure favourable growth of the test plants under natural light throughout the year (§ 5.1, p. 13).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-04' AND x.code = 'REQ-05';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn als Testpflanzenart Phragmites australis (Schilf) gewählt ist (FLLTP-RHZ-08) und die Pflanzenzahl je Gefäß (FLLTP-RHZ-11) mindestens 8 × Skalierungsfaktor beträgt; beide Felder liegen auf anderen Blättern und müssen ausgefüllt sein. Grund: vorgeschrieben ist Phragmites australis im 9 × 9 Container, 8 Pflanzen je Gefäß von 800 × 800 mm (§ 5.8, S. 15; § 7.1, S. 17); bei größeren Gefäßen sind Angaben wie die Pflanzdichte an die Gefäßgröße anzupassen (§ 5.2, S. 13), der Faktor kommt aus FLLTP-RHZ-05. Beispiel 1000 × 1000 mm: Faktor 1,5625, also mindestens 12,5 → 13 Pflanzen.
[EN] Passes when the test plant species is Phragmites australis (reed) (FLLTP-RHZ-08) and the number of plants per vessel (FLLTP-RHZ-11) is at least 8 × scaling factor; both fields sit on other sheets and must be filled. Reason: Phragmites australis in a 9 × 9 container is prescribed, 8 plants per 800 × 800 mm vessel (§ 5.8, p. 15; § 7.1, p. 17); for larger vessels, figures such as planting density must be adapted to the vessel size (§ 5.2, p. 13), the factor comes from FLLTP-RHZ-05. Example 1000 × 1000 mm: factor 1.5625, i.e. at least 12.5 → 13 plants.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-04' AND x.code = 'REQ-10';
UPDATE fields x SET description = 'Zahl der Kontrollgefäße: pro Prüfung — unabhängig von der Anzahl der zu prüfenden Abdichtungen — 3 Gefäße ohne Wasserablauf, wasserdicht, ohne Widerlager und ohne Abdichtung; sie dienen als Kontrolle für das Pflanzenwachstum (§ 5.2, S. 13–14; § 4, S. 12; § 7.2, S. 19). Tor REQ-06 verlangt genau 3. Die Zahl bestimmt die Kontrollgefäß-Zeilen der Auswertungsblätter FLLTP-RHZ-10 und 13 bis 16.
[EN] Number of control vessels: per test — regardless of the number of sealings tested — 3 vessels without drain, watertight, without abutment and without sealing; they serve as the control for plant growth (§ 5.2, pp. 13–14; § 4, p. 12; § 7.2, p. 19). Gate REQ-06 requires exactly 3. The number defines the control-vessel rows of the evaluation sheets FLLTP-RHZ-10 and 13 to 16.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'anzahl_kontrollgefaesse';
UPDATE fields x SET description = 'Zahl der Prüfgefäße für die hier geprüfte Abdichtung: je zu untersuchender Abdichtung 8 Prüfgefäße mit Wasserablauf (§ 5.2, S. 14; § 4, S. 12). Tor REQ-06 verlangt genau 8; die Zahl bestimmt die Zeilen der Halmzählung (FLLTP-RHZ-13 bis 16) und der Endauswertung (FLLTP-RHZ-17). Dieses Projekt deckt eine Abdichtung ab.
[EN] Number of test vessels for the sealing tested here: 8 test vessels with drain per sealing under investigation (§ 5.2, p. 14; § 4, p. 12). Gate REQ-06 requires exactly 8; the number defines the rows of the shoot counts (FLLTP-RHZ-13 to 16) and of the final evaluation (FLLTP-RHZ-17). This project covers one sealing.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'anzahl_pruefgefaesse';
UPDATE fields x SET description = 'Lichte Breite des Gefäßes in mm, am Gefäß gemessen. Mindestinnenmaß 800 × 800 × 250 mm (§ 5.2, S. 13; Abb. 1); größere Gefäße sind bei einbautechnischen Erfordernissen zulässig, z. B. bei Abdichtungen mit einer Dicke über rund 50 mm — dann sind Düngung, Pflanzdichte usw. anzupassen (§ 5.2, S. 13). Tor REQ-06 prüft ≥ 800 mm; Länge × Breite gehen in die Grundfläche (D1) und den Skalierungsfaktor (D2) ein.
[EN] Clear width of the vessel in mm, measured on the vessel. Minimum inner dimensions 800 × 800 × 250 mm (§ 5.2, p. 13; Fig. 1); larger vessels are permitted where installation requires it, e.g. for sealings thicker than about 50 mm — fertilising, planting density etc. must then be adapted (§ 5.2, p. 13). Gate REQ-06 checks ≥ 800 mm; length × width feed the base area (D1) and the scaling factor (D2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'gefaess_innenmass_b_mm';
UPDATE fields x SET description = 'Lichte Höhe des Gefäßes in mm, am Gefäß gemessen. Mindestinnenmaß 800 × 800 × 250 mm (§ 5.2, S. 13; Abb. 1); Tor REQ-06 prüft ≥ 250 mm. Die Höhe muss Widerlager, ggf. Trennlage, beide Prüfmuster und die Vegetationstragschicht (170 ±10) mm aufnehmen; die Prüfmuster müssen im eingebauten Zustand bis zur Gefäßoberkante reichen (§ 7.1, S. 17; § 5.6, S. 14).
[EN] Clear height of the vessel in mm, measured on the vessel. Minimum inner dimensions 800 × 800 × 250 mm (§ 5.2, p. 13; Fig. 1); gate REQ-06 checks ≥ 250 mm. The height must accommodate abutment, separation layer if any, both specimens and the (170 ±10) mm substrate; the installed specimens must reach the top edge of the vessel (§ 7.1, p. 17; § 5.6, p. 14).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'gefaess_innenmass_h_mm';
UPDATE fields x SET description = 'Lichte Länge des Gefäßes in mm, am Gefäß gemessen. Mindestinnenmaß 800 × 800 × 250 mm (§ 5.2, S. 13; Abb. 1); größere Gefäße sind bei einbautechnischen Erfordernissen zulässig (z. B. Dicke der Abdichtung über rund 50 mm), dann sind alle auf das Mindestmaß bezogenen Angaben anzupassen (§ 5.2, S. 13). Tor REQ-06 prüft ≥ 800 mm; Länge × Breite gehen in D1/D2 ein. Die Nahtmaße der Abb. 2 und 3 (S. 18) gelten für 800 × 800 × 250 mm.
[EN] Clear length of the vessel in mm, measured on the vessel. Minimum inner dimensions 800 × 800 × 250 mm (§ 5.2, p. 13; Fig. 1); larger vessels are permitted where installation requires it (e.g. sealing thicker than about 50 mm), in which case all figures referring to the minimum size must be adapted (§ 5.2, p. 13). Gate REQ-06 checks ≥ 800 mm; length × width feed D1/D2. The seam dimensions of Figs. 2 and 3 (p. 18) refer to 800 × 800 × 250 mm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'gefaess_innenmass_l_mm';
UPDATE fields x SET description = 'Werkstoff der Prüf- und Kontrollgefäße: korrosionsfest, mit stabiler Wandung und pflanzenverträglich (§ 5.2, S. 13; § 3.1, S. 9). Aus Lieferschein oder Datenblatt übernehmen; die Beschaffung der Gefäße kann Auftraggeber oder Prüfinstitut übernehmen, je nach Vertrag (§ 11, S. 24). Freitext, kein Tor.
[EN] Material of the test and control vessels: corrosion-resistant, with a stable wall and plant-compatible (§ 5.2, p. 13; § 3.1, p. 9). Take it from the delivery note or data sheet; the vessels may be procured by the client or the test institute as agreed in the contract (§ 11, p. 24). Free text, no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'gefaess_material';
UPDATE fields x SET description = '„Ja“, wenn zwischen Gefäßwand bzw. Widerlager und Abdichtung eine Trennlage liegt. Sie ist zulässig, wenn das Produkt nicht polystyrolverträglich ist (§ 3.3, S. 9; § 5.4, S. 14), muss produktverträglich und wasserdurchlässig sein, damit Undichtigkeiten des Produkts während der Prüfung erkannt werden (§ 5.4, S. 14); Materialbedarf ca. 1,5 m² je Gefäß 800 × 800 mm. Beschaffung und Einbau sind Sache des Auftraggebers (§ 11, S. 24); verlegt wird sie auf dem Widerlager oder an der Innenseite des Prüfgefäßes (§ 7.1, S. 17). Kein Tor; geht nach FLLTP-RHZ-09.
[EN] ''Yes'' if a separation layer lies between vessel wall or abutment and the sealing. It is permitted when the product is not compatible with polystyrene (§ 3.3, p. 9; § 5.4, p. 14), must be product-compatible and water-permeable so that leaks of the product can be detected during the test (§ 5.4, p. 14); material need about 1.5 m² per 800 × 800 mm vessel. Procurement and installation are the client''s task (§ 11, p. 24); it is laid on the abutment or on the inside of the test vessel (§ 7.1, p. 17). No gate; carried into FLLTP-RHZ-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'trennlage_eingebaut';
UPDATE fields x SET description = 'Nur bei eingebauter Trennlage: bestätigen, dass sie wasserdurchlässig ist. Für die Prüfung ist eine wasserdurchlässige Trennlage erforderlich, damit während der Prüfung auftretende Undichtigkeiten des zu prüfenden Produkts über den Wasserablauf feststellbar bleiben (§ 5.4, S. 14). Nachweis aus dem Datenblatt der Trennlage; kein Tor liest das Feld.
[EN] Only when a separation layer is installed: confirm that it is water-permeable. A water-permeable separation layer is required for the test so that leaks of the product under test remain detectable via the drain during the test (§ 5.4, p. 14). Evidence from the separation layer''s data sheet; no gate reads this field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'trennlage_wasserdurchlaessig';
UPDATE fields x SET description = 'Durchmesser des Wasserablaufs im Boden der Prüfgefäße: Ø 40 mm, nur bei den Prüfgefäßen; die Kontrollgefäße sind wasserdicht (Abb. 1, S. 13). Über den Ablauf werden Undichtigkeiten — und damit Beschädigungen der zu prüfenden Abdichtung — während der Prüfung erkennbar (§ 5.2, S. 13). Tor REQ-06 verlangt genau 40 mm.
[EN] Diameter of the drain in the floor of the test vessels: Ø 40 mm, test vessels only; the control vessels are watertight (Fig. 1, p. 13). The drain makes leaks — and thus damage to the sealing under test — detectable during the test (§ 5.2, p. 13). Gate REQ-06 requires exactly 40 mm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'wasserablauf_durchmesser_mm';
UPDATE fields x SET description = 'Nur wenn ein Widerlager eingebaut ist: Dicke der Polystyrolplatten in mm, aus dem Lieferschein. Vorgabe 10 ±1 mm, also 9 bis 11 mm (§ 5.3, S. 14); Tor REQ-06 prüft diesen Bereich. Materialbedarf ca. 1,5 m² je Gefäß 800 × 800 mm (§ 5.3, S. 14).
[EN] Only when an abutment is installed: thickness of the polystyrene boards in mm, from the delivery note. Requirement 10 ±1 mm, i.e. 9 to 11 mm (§ 5.3, p. 14); gate REQ-06 checks this range. Material need about 1.5 m² per 800 × 800 mm vessel (§ 5.3, p. 14).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'widerlager_dicke_mm';
UPDATE fields x SET description = 'Werkstoff des Widerlagers: Polystyrolplatten (DAA dh), mit denen die Gefäßinnenseiten allseitig einlagig ausgekleidet werden, damit sich das zu prüfende Produkt unter dem Rhizomdruck dehnen kann (§ 3.2, S. 9; § 5.3, S. 14; Abb. 1). Aus Lieferschein oder Datenblatt übernehmen; Beschaffung und Einbau durch das Prüfinstitut (§ 11, S. 24). Freitext, kein Tor.
[EN] Material of the abutment: polystyrene boards (DAA dh) lining the inside of the vessel on all sides in a single layer so that the product under test can expand under rhizome pressure (§ 3.2, p. 9; § 5.3, p. 14; Fig. 1). Take it from the delivery note or data sheet; procured and installed by the test institute (§ 11, p. 24). Free text, no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'widerlager_material';
UPDATE fields x SET description = '„Ja“, wenn die Gefäßinnenseiten der Prüfgefäße mit Polystyrolplatten ausgekleidet sind — der Regelfall, damit sich das Produkt unter dem Rhizomdruck der Testpflanzen dehnen kann (§ 3.2, S. 9; § 5.3, S. 14; Abb. 1). „Nein“ ist nur bei starren Werkstoffen (z. B. Gussasphalt) zulässig (§ 3.2, S. 9); dann das Begründungsfeld ausfüllen. Bei Ja prüft Tor REQ-06 die Plattendicke 10 ±1 mm, bei Nein entfällt dieser Teil. Kontrollgefäße erhalten kein Widerlager (§ 7.2, S. 19).
[EN] ''Yes'' if the inside of the test vessels is lined with polystyrene boards — the normal case, so that the product can expand under the rhizome pressure of the test plants (§ 3.2, p. 9; § 5.3, p. 14; Fig. 1). ''No'' is permitted only for rigid materials (e.g. mastic asphalt) (§ 3.2, p. 9); then fill in the reason field. For Yes, gate REQ-06 checks the board thickness 10 ±1 mm; for No that term is dropped. Control vessels get no abutment (§ 7.2, p. 19).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'widerlager_eingebaut';
UPDATE fields x SET description = 'Nur bei „Widerlager eingebaut“ = Nein: Begründung, warum auf das Widerlager verzichtet wird. Zulässig ist der Verzicht bei starren Werkstoffen, z. B. Gussasphalt (§ 3.2, S. 9); nennen Sie den Werkstoff laut Werkstoffbezeichnung des Herstellers (§ 6, S. 16) und warum er als starr gilt. Die Angabe gehört zu den Angaben über die Vorbereitung der Prüfgefäße im Prüfbericht (§ 9, S. 22). Freitext, kein Tor.
[EN] Only when ''Abutment installed'' = No: reason for omitting the abutment. Omission is permitted for rigid materials, e.g. mastic asphalt (§ 3.2, p. 9); name the material per the manufacturer''s material designation (§ 6, p. 16) and why it counts as rigid. The entry belongs to the details on the preparation of the test vessels in the test report (§ 9, p. 22). Free text, no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'widerlager_verzicht_begruendung';
UPDATE fields x SET description = 'Bestätigung, dass die 3 Kontrollgefäße wasserdicht ausgeführt sind, also ohne Wasserablauf (§ 5.2, S. 13–14; Abb. 1, S. 13). Der Wasserablauf Ø 40 mm ist nur bei den Prüfgefäßen vorzusehen. Tor REQ-06 verlangt den Haken.
[EN] Attest that the 3 control vessels are made watertight, i.e. without a drain (§ 5.2, pp. 13–14; Fig. 1, p. 13). The Ø 40 mm drain is provided in the test vessels only. Gate REQ-06 requires the tick.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'kontrollgefaesse_wasserdicht';
UPDATE fields x SET description = 'Wird berechnet (D1): Innenmaß Länge × Breite / 1 000 000, in m². Für das Mindestgefäß 800 × 800 mm ergibt sich 0,64 m² (§ 5.2, S. 13). Zwischenwert für den Skalierungsfaktor (D2); nicht von Hand eintragen.
[EN] Computed (D1): inner length × inner width / 1 000 000, in m². For the minimum vessel 800 × 800 mm this gives 0.64 m² (§ 5.2, p. 13). Intermediate value for the scaling factor (D2); do not enter by hand.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'gefaess_flaeche_m2';
UPDATE fields x SET description = 'Wird berechnet (D2): Grundfläche / 0,64 m², also das Verhältnis zum Mindestgefäß 800 × 800 mm; 1,0 beim Mindestgefäß, z. B. 1,5625 bei 1000 × 1000 mm. Weil alle auf das Mindestmaß bezogenen Angaben (z. B. Düngung, Pflanzdichte) an größer dimensionierte Gefäße anzupassen sind (§ 5.2, S. 13), multiplizieren die Tore REQ-10 (8 Pflanzen je Gefäß, § 5.8, S. 15) und REQ-14 (5 g Dünger in 20 l, § 7.3, S. 20) ihre Sollwerte mit diesem Faktor. Nicht von Hand eintragen.
[EN] Computed (D2): base area / 0.64 m², i.e. the ratio to the minimum vessel 800 × 800 mm; 1.0 for the minimum vessel, e.g. 1.5625 for 1000 × 1000 mm. Because all figures referring to the minimum size (e.g. fertilising, planting density) must be adapted to larger vessels (§ 5.2, p. 13), gates REQ-10 (8 plants per vessel, § 5.8, p. 15) and REQ-14 (5 g fertiliser in 20 l, § 7.3, p. 20) multiply their targets by this factor. Do not enter by hand.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.symbol = 'gefaess_skalierungsfaktor';
UPDATE equations x SET description = 'Berechnet die Grundfläche eines Gefäßes aus den Innenmaßen: gefaess_flaeche_m2 [m²] = Länge [mm] × Breite [mm] / 1 000 000. Die Richtlinie druckt keine Gleichung, sondern nur das Mindestinnenmaß 800 × 800 × 250 mm (§ 5.2, S. 13; Abb. 1), aus dem 0,64 m² folgen; die Formel ist der Rechenweg des Wizards. Das Ergebnis speist D2 (Skalierungsfaktor).
[EN] Computes the base area of a vessel from its inner dimensions: gefaess_flaeche_m2 [m²] = length [mm] × width [mm] / 1 000 000. The guideline prints no equation, only the minimum inner dimensions 800 × 800 × 250 mm (§ 5.2, p. 13; Fig. 1), which give 0.64 m²; the formula is the Wizard''s calculation path. The result feeds D2 (scaling factor).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.equation_number = 'FLLTP-RHZ-05-D1';
UPDATE equations x SET description = 'gefaess_skalierungsfaktor [-] = gefaess_flaeche_m2 [m²] / 0,64 m². Die Richtlinie verlangt, alle auf das Mindestgefäß 800 × 800 mm bezogenen Angaben (z. B. Düngung, Pflanzdichte) an größer dimensionierte Gefäße anzupassen (§ 5.2, S. 13); der Faktor setzt das proportional zur Grundfläche um (Wizard-Rechenweg, keine gedruckte Gleichung). Ergebnis 1,0 beim Mindestgefäß; er geht in REQ-10 (8 Pflanzen je Gefäß, § 5.8, S. 15) und REQ-14 (5 g Dünger in 20 l je Gabe, § 7.3, S. 20) ein.
[EN] gefaess_skalierungsfaktor [-] = gefaess_flaeche_m2 [m²] / 0.64 m². The guideline requires all figures referring to the minimum vessel 800 × 800 mm (e.g. fertilising, planting density) to be adapted to larger vessels (§ 5.2, p. 13); the factor implements this in proportion to the base area (Wizard calculation path, no printed equation). Result 1.0 for the minimum vessel; it feeds REQ-10 (8 plants per vessel, § 5.8, p. 15) and REQ-14 (5 g fertiliser in 20 l per dose, § 7.3, p. 20).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.equation_number = 'FLLTP-RHZ-05-D2';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn: Innenmaße Länge ≥ 800 mm, Breite ≥ 800 mm, Höhe ≥ 250 mm (§ 5.2, S. 13; Abb. 1); genau 8 Prüfgefäße und 3 Kontrollgefäße (§ 5.2, S. 14); Wasserablauf Ø 40 mm (Abb. 1, S. 13); Haken „Kontrollgefäße wasserdicht“ (§ 5.2, S. 13); und — nur wenn ein Widerlager eingebaut ist — Plattendicke 9 bis 11 mm (10 ±1 mm, § 5.3, S. 14). Ohne Widerlager (starrer Werkstoff, z. B. Gussasphalt, § 3.2, S. 9) entfällt der letzte Teil. Alle genannten Felder müssen ausgefüllt sein, sonst bleibt das Tor rot.
[EN] Passes when: inner length ≥ 800 mm, width ≥ 800 mm, height ≥ 250 mm (§ 5.2, p. 13; Fig. 1); exactly 8 test vessels and 3 control vessels (§ 5.2, p. 14); drain Ø 40 mm (Fig. 1, p. 13); tick ''Control vessels made watertight'' (§ 5.2, p. 13); and — only if an abutment is installed — board thickness 9 to 11 mm (10 ±1 mm, § 5.3, p. 14). Without abutment (rigid material, e.g. mastic asphalt, § 3.2, p. 9) the last term is dropped. All named fields must be filled, otherwise the gate stays red.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-05' AND x.code = 'REQ-06';
UPDATE fields x SET description = 'Karbonatgehalt (CaCO₃) der Vegetationstragschicht nach Scheibler in M.-%, aus dem Laborbericht der Eingangsprüfung (Bestimmung nach VDLUFA-Vorgaben). Sollbereich 1 – 10 M.-% (Tab. 1 Spalte 7, S. 14); Tor REQ-07 prüft ihn.
[EN] Carbonate content (CaCO₃) of the substrate by the Scheibler method in % by mass, from the laboratory report of the incoming inspection (determined per VDLUFA rules). Target range 1 – 10 % by mass (Tab. 1 column 7, p. 14); gate REQ-07 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.symbol = 'vts_caco3_scheibler_prozent';
UPDATE fields x SET description = 'Wird berechnet (D1): untere + obere Vegetationstragschicht in mm; beide Dicken werden beim Einbau auf FLLTP-RHZ-09 eingetragen. Geforderte Gesamtschichtdicke (170 ±10) mm, bei der der Substratbedarf ca. 110 l je Gefäß 800 × 800 mm beträgt (§ 5.6, S. 14); Tor REQ-26 prüft 160 bis 180 mm. Nicht von Hand eintragen.
[EN] Computed (D1): lower + upper substrate layer in mm; both thicknesses are entered during installation on FLLTP-RHZ-09. Required total thickness (170 ±10) mm, at which the substrate need is about 110 l per 800 × 800 mm vessel (§ 5.6, p. 14); gate REQ-26 checks 160 to 180 mm. Do not enter by hand.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.symbol = 'vts_gesamt_dicke_mm';
UPDATE fields x SET description = 'Kaliumgehalt (K₂O) der Vegetationstragschicht im CAT-Auszug in mg/l, aus dem Laborbericht der Eingangsprüfung (VDLUFA). Sollwert ≤ 100 mg/l (Tab. 1 Spalte 6, S. 14); Tor REQ-07 prüft ihn.
[EN] Potassium content (K₂O) of the substrate in the CAT extract in mg/l, from the laboratory report of the incoming inspection (VDLUFA). Target ≤ 100 mg/l (Tab. 1 column 6, p. 14); gate REQ-07 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.symbol = 'vts_k2o_cat_mg_l';
UPDATE fields x SET description = 'Körnung des gewaschenen Sandes der Vegetationstragschicht laut Lieferschein oder Sieblinie: vorgeschrieben 0–4 mm (§ 5.6, S. 14; § 3.4, S. 9). Die Schicht wird zweischichtig eingebaut und steht in unmittelbarem Kontakt zur Abdichtung; Beschaffung und Einbau durch das Prüfinstitut (§ 11, S. 24). Freitext, kein Tor.
[EN] Grain size of the washed sand of the substrate per delivery note or sieve curve: prescribed 0–4 mm (§ 5.6, p. 14; § 3.4, p. 9). The layer is installed in two layers and is in direct contact with the sealing; procured and installed by the test institute (§ 11, p. 24). Free text, no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.symbol = 'vts_koernung';
UPDATE fields x SET description = 'Stickstoffgehalt (N) der Vegetationstragschicht im CAT-Auszug in mg/l, aus dem Laborbericht der Eingangsprüfung (VDLUFA). Sollwert ≤ 50 mg/l (Tab. 1 Spalte 4, S. 14); Tor REQ-07 prüft ihn.
[EN] Nitrogen content (N) of the substrate in the CAT extract in mg/l, from the laboratory report of the incoming inspection (VDLUFA). Target ≤ 50 mg/l (Tab. 1 column 4, p. 14); gate REQ-07 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.symbol = 'vts_n_cat_mg_l';
UPDATE fields x SET description = 'Phosphatgehalt (P₂O₅) der Vegetationstragschicht im CAT-Auszug in mg/l, aus dem Laborbericht der Eingangsprüfung (VDLUFA). Sollwert ≤ 25 mg/l (Tab. 1 Spalte 5, S. 14); Tor REQ-07 prüft ihn.
[EN] Phosphate content (P₂O₅) of the substrate in the CAT extract in mg/l, from the laboratory report of the incoming inspection (VDLUFA). Target ≤ 25 mg/l (Tab. 1 column 5, p. 14); gate REQ-07 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.symbol = 'vts_p2o5_cat_mg_l';
UPDATE fields x SET description = 'pH-Wert der Vegetationstragschicht im CaCl₂-Auszug, aus dem Laborbericht der Eingangsprüfung (VDLUFA). Sollbereich 6,0 – 7,5 (Tab. 1 Spalte 1, S. 14); Tor REQ-07 prüft ihn.
[EN] pH of the substrate in the CaCl₂ extract, from the laboratory report of the incoming inspection (VDLUFA). Target range 6.0 – 7.5 (Tab. 1 column 1, p. 14); gate REQ-07 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.symbol = 'vts_ph_cacl2';
UPDATE fields x SET description = 'Salzgehalt der Vegetationstragschicht im CaSO₄-Auszug in g/l, aus dem Laborbericht der Eingangsprüfung (VDLUFA). Sollwert ≤ 0,5 g/l (Tab. 1 Spalte 3, S. 14); Tor REQ-07 prüft ihn.
[EN] Salt content of the substrate in the CaSO₄ extract in g/l, from the laboratory report of the incoming inspection (VDLUFA). Target ≤ 0.5 g/l (Tab. 1 column 3, p. 14); gate REQ-07 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.symbol = 'vts_salz_caso4_g_l';
UPDATE fields x SET description = 'Salzgehalt der Vegetationstragschicht im H₂O-Auszug in g/l, aus dem Laborbericht der Eingangsprüfung (VDLUFA). Sollwert ≤ 1,0 g/l (Tab. 1 Spalte 2, S. 14); Tor REQ-07 prüft ihn.
[EN] Salt content of the substrate in the H₂O extract in g/l, from the laboratory report of the incoming inspection (VDLUFA). Target ≤ 1.0 g/l (Tab. 1 column 2, p. 14); gate REQ-07 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.symbol = 'vts_salz_h2o_g_l';
UPDATE equations x SET description = 'vts_gesamt_dicke_mm [mm] = vts_untere_schicht_dicke_mm + vts_obere_schicht_dicke_mm; beide Eingaben stehen auf FLLTP-RHZ-09 (Einbau). Sollwerte: untere Schicht (20 ±5) mm, obere Schicht (150 ±5) mm (§ 7.1, S. 17), zusammen die geforderte Schichtdicke von (170 ±10) mm, bei der der Substratbedarf ca. 110 l je Gefäß 800 × 800 mm beträgt (§ 5.6, S. 14). Das Ergebnis liest Tor REQ-26.
[EN] vts_gesamt_dicke_mm [mm] = vts_untere_schicht_dicke_mm + vts_obere_schicht_dicke_mm; both inputs are entered on FLLTP-RHZ-09 (installation). Targets: lower layer (20 ±5) mm, upper layer (150 ±5) mm (§ 7.1, p. 17), together the required layer thickness of (170 ±10) mm, at which the substrate need is about 110 l per 800 × 800 mm vessel (§ 5.6, p. 14). The result is read by gate REQ-26.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.equation_number = 'FLLTP-RHZ-06-D1';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn alle sieben Laborwerte der Eingangsprüfung in den Grenzen der Tab. 1 liegen: pH (CaCl₂) 6,0 – 7,5; Salz (H₂O) ≤ 1,0 g/l; Salz (CaSO₄) ≤ 0,5 g/l; N (CAT) ≤ 50 mg/l; P₂O₅ (CAT) ≤ 25 mg/l; K₂O (CAT) ≤ 100 mg/l; CaCO₃ (Scheibler) 1 – 10 M.-% (Tab. 1, S. 14). Tragen Sie alle sieben Werte aus dem Laborbericht ein; fehlt einer, bleibt das Tor rot. Grund: Die Vegetationstragschicht muss ein für die Testpflanzen geeignetes Kultursubstrat aus gewaschenem Sand 0–4 mm sein (§ 5.6, S. 14; § 3.4, S. 9).
[EN] Passes when all seven laboratory values of the incoming inspection lie within the Tab. 1 limits: pH (CaCl₂) 6.0 – 7.5; salt (H₂O) ≤ 1.0 g/l; salt (CaSO₄) ≤ 0.5 g/l; N (CAT) ≤ 50 mg/l; P₂O₅ (CAT) ≤ 25 mg/l; K₂O (CAT) ≤ 100 mg/l; CaCO₃ (Scheibler) 1 – 10 % by mass (Tab. 1, p. 14). Enter all seven values from the laboratory report; a missing value keeps the gate red. Reason: the substrate must be a culture substrate of washed sand 0–4 mm suitable for the test plants (§ 5.6, p. 14; § 3.4, p. 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.code = 'REQ-07';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn die berechnete Gesamtdicke der Vegetationstragschicht zwischen 160 und 180 mm liegt, also (170 ±10) mm (§ 5.6, S. 14). Dazu müssen auf FLLTP-RHZ-09 die Dicken der unteren Schicht (20 ±5) mm und der oberen Schicht (150 ±5) mm eingetragen sein (§ 7.1, S. 17); ohne diese beiden Eingaben kann der Wert nicht berechnet werden und das Tor bleibt rot. Die Gesamtdicke bestimmt den Substratbedarf von ca. 110 l je Gefäß 800 × 800 mm (§ 5.6, S. 14).
[EN] Passes when the computed total substrate thickness lies between 160 and 180 mm, i.e. (170 ±10) mm (§ 5.6, p. 14). This requires the lower-layer thickness (20 ±5) mm and the upper-layer thickness (150 ±5) mm to be entered on FLLTP-RHZ-09 (§ 7.1, p. 17); without these two inputs the value cannot be computed and the gate stays red. The total thickness determines the substrate need of about 110 l per 800 × 800 mm vessel (§ 5.6, p. 14).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-06' AND x.code = 'REQ-26';
UPDATE fields x SET description = '„Ja“, wenn der verwendete Mehrnährstoffdünger wasserlöslich und chloridarm ist (§ 5.7, S. 15); aus der Düngerdeklaration bzw. dem Produktdatenblatt. Tor REQ-08 verlangt Ja. Der Dünger wird monatlich mit 5 g je Gefäß 800 × 800 mm in 20 l Wasser gelöst ausgebracht (§ 7.3, S. 20; FLLTP-RHZ-12).
[EN] ''Yes'' if the compound fertiliser used is water-soluble and low in chloride (§ 5.7, p. 15); from the fertiliser declaration or product data sheet. Gate REQ-08 requires Yes. The fertiliser is applied monthly at 5 g per 800 × 800 mm vessel dissolved in 20 l of water (§ 7.3, p. 20; FLLTP-RHZ-12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'duenger_chloridarm';
UPDATE fields x SET description = 'Kaliumanteil (K₂O) des Mehrnährstoffdüngers in %, aus der Deklaration. Vorgabe ca. 15 % K₂O (§ 5.7, S. 15). Kein eigenes Tor, da die Richtlinie einen „ca.“-Wert nennt; das Produkt ist im Prüfbericht zu dokumentieren.
[EN] Potassium share (K₂O) of the compound fertiliser in %, from the declaration. Requirement about 15 % K₂O (§ 5.7, p. 15). No separate gate because the guideline gives an approximate value; document the product in the test report.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'duenger_k2o_prozent';
UPDATE fields x SET description = 'Magnesiumanteil (MgO) des Mehrnährstoffdüngers in %, aus der Deklaration. Vorgabe ca. 2 % MgO (§ 5.7, S. 15). Kein eigenes Tor, da die Richtlinie einen „ca.“-Wert nennt; das Produkt ist im Prüfbericht zu dokumentieren.
[EN] Magnesium share (MgO) of the compound fertiliser in %, from the declaration. Requirement about 2 % MgO (§ 5.7, p. 15). No separate gate because the guideline gives an approximate value; document the product in the test report.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'duenger_mgo_prozent';
UPDATE fields x SET description = 'Stickstoffanteil (N) des Mehrnährstoffdüngers in %, aus der Deklaration. Vorgabe ca. 15 % N (§ 5.7, S. 15). Kein eigenes Tor, da die Richtlinie einen „ca.“-Wert nennt; der Wert wird in das Düngungsblatt FLLTP-RHZ-12 übernommen (Gabe 5 g je Gefäß in 20 l Wasser, § 7.3, S. 20).
[EN] Nitrogen share (N) of the compound fertiliser in %, from the declaration. Requirement about 15 % N (§ 5.7, p. 15). No separate gate because the guideline gives an approximate value; the value is carried into the fertilising sheet FLLTP-RHZ-12 (dose 5 g per vessel in 20 l of water, § 7.3, p. 20).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'duenger_n_prozent';
UPDATE fields x SET description = 'Phosphatanteil (P₂O₅) des Mehrnährstoffdüngers in %, aus der Deklaration. Vorgabe ca. 10 % P₂O₅ (§ 5.7, S. 15). Kein eigenes Tor, da die Richtlinie einen „ca.“-Wert nennt; das Produkt ist im Prüfbericht zu dokumentieren.
[EN] Phosphate share (P₂O₅) of the compound fertiliser in %, from the declaration. Requirement about 10 % P₂O₅ (§ 5.7, p. 15). No separate gate because the guideline gives an approximate value; document the product in the test report.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'duenger_p2o5_prozent';
UPDATE fields x SET description = '„Ja“, wenn der Dünger laut Deklaration zusätzlich die Spurennährelemente Eisen (Fe), Kupfer (Cu), Molybdän (Mo), Mangan (Mn), Bor (B) und Zink (Zn) enthält (§ 5.7, S. 15). Alle sechs müssen enthalten sein; Tor REQ-08 verlangt Ja.
[EN] ''Yes'' if, per its declaration, the fertiliser additionally contains the trace nutrients iron (Fe), copper (Cu), molybdenum (Mo), manganese (Mn), boron (B) and zinc (Zn) (§ 5.7, p. 15). All six must be present; gate REQ-08 requires Yes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'duenger_spurelemente_vorhanden';
UPDATE fields x SET description = 'Ammoniumgehalt des Gießwassers in mg/l, aus der Wasseranalyse der Eingangsprüfung. Richtwert ≤ 0,5 mg/l (Tab. 2 Zeile 2, S. 15); Tor REQ-09 prüft ihn. Die Ausgangsbedingungen entsprechen den Richtwerten für Füllwasser der FLL-Richtlinien für private Schwimm- und Badeteiche 2017 (§ 5.9, S. 15).
[EN] Ammonium content of the irrigation water in mg/l, from the water analysis of the incoming inspection. Guide value ≤ 0.5 mg/l (Tab. 2 row 2, p. 15); gate REQ-09 checks it. The initial conditions correspond to the fill-water guide values of the FLL private swimming-pond guidelines 2017 (§ 5.9, p. 15).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'wasser_ammonium_mg_l';
UPDATE fields x SET description = 'Eisengehalt des Gießwassers in mg/l, aus der Wasseranalyse der Eingangsprüfung. Richtwert ≤ 0,2 mg/l (Tab. 2 Zeile 3, S. 15); Tor REQ-09 prüft ihn.
[EN] Iron content of the irrigation water in mg/l, from the water analysis of the incoming inspection. Guide value ≤ 0.2 mg/l (Tab. 2 row 3, p. 15); gate REQ-09 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'wasser_eisen_mg_l';
UPDATE fields x SET description = 'Härte des Gießwassers als Summe der Erdalkalien in mmol/l (entspricht der Gesamthärte), aus der Wasseranalyse. Richtwert ≥ 1,0 mmol/l, entspricht ≥ 5,6 dH° (Tab. 2 Zeile 5, S. 15); Tor REQ-09 prüft ihn. Liegt der Laborwert in dH° vor, in mmol/l umrechnen.
[EN] Hardness of the irrigation water as the sum of alkaline earths in mmol/l (equals total hardness), from the water analysis. Guide value ≥ 1.0 mmol/l, corresponding to ≥ 5.6 dH° (Tab. 2 row 5, p. 15); gate REQ-09 checks it. If the laboratory reports dH°, convert to mmol/l.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'wasser_haerte_mmol_l';
UPDATE fields x SET description = 'Elektrische Leitfähigkeit des Gießwassers in µS/cm bei 20 °C, aus der Wasseranalyse. Richtwert ≤ 1000,0 µS/cm bei 20 °C (Tab. 2 Zeile 6, S. 15); Tor REQ-09 prüft ihn. Auf die Bezugstemperatur 20 °C achten.
[EN] Electrical conductivity of the irrigation water in µS/cm at 20 °C, from the water analysis. Guide value ≤ 1000.0 µS/cm at 20 °C (Tab. 2 row 6, p. 15); gate REQ-09 checks it. Mind the 20 °C reference temperature.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'wasser_leitfaehigkeit_uS_cm';
UPDATE fields x SET description = 'Mangangehalt des Gießwassers in mg/l, aus der Wasseranalyse der Eingangsprüfung. Richtwert ≤ 0,05 mg/l (Tab. 2 Zeile 7, S. 15); Tor REQ-09 prüft ihn.
[EN] Manganese content of the irrigation water in mg/l, from the water analysis of the incoming inspection. Guide value ≤ 0.05 mg/l (Tab. 2 row 7, p. 15); gate REQ-09 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'wasser_mangan_mg_l';
UPDATE fields x SET description = 'Nitratgehalt des Gießwassers in mg/l, aus der Wasseranalyse der Eingangsprüfung. Richtwert ≤ 50,0 mg/l (Tab. 2 Zeile 8, S. 15); Tor REQ-09 prüft ihn.
[EN] Nitrate content of the irrigation water in mg/l, from the water analysis of the incoming inspection. Guide value ≤ 50.0 mg/l (Tab. 2 row 8, p. 15); gate REQ-09 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'wasser_nitrat_mg_l';
UPDATE fields x SET description = 'ortho-Phosphatgehalt des Gießwassers, angegeben als P, in mg/l, aus der Wasseranalyse. Richtwert ≤ 0,01 mg/l (Tab. 2 Zeile 9, S. 15); Tor REQ-09 prüft ihn. Angabe als P, nicht als PO₄.
[EN] ortho-phosphate content of the irrigation water, expressed as P, in mg/l, from the water analysis. Guide value ≤ 0.01 mg/l (Tab. 2 row 9, p. 15); gate REQ-09 checks it. Report as P, not as PO₄.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'wasser_ortho_phosphat_mg_l';
UPDATE fields x SET description = 'Gesamtphosphor (P_ges) des Gießwassers in mg/l, aus der Wasseranalyse der Eingangsprüfung. Richtwert ≤ 0,03 mg/l (Tab. 2 Zeile 4, S. 15); Tor REQ-09 prüft ihn.
[EN] Total phosphorus (P_total) of the irrigation water in mg/l, from the water analysis of the incoming inspection. Guide value ≤ 0.03 mg/l (Tab. 2 row 4, p. 15); gate REQ-09 checks it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'wasser_p_gesamt_mg_l';
UPDATE fields x SET description = 'pH-Wert des Gießwassers, aus der Wasseranalyse der Eingangsprüfung. Richtwert 6,0 – 9,0 (Tab. 2 Zeile 10, S. 15); Tor REQ-09 prüft den Bereich.
[EN] pH of the irrigation water, from the water analysis of the incoming inspection. Guide value 6.0 – 9.0 (Tab. 2 row 10, p. 15); gate REQ-09 checks the range.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'wasser_ph';
UPDATE fields x SET description = 'Säurekapazität K_S4,3 des Gießwassers in mmol/l (entspricht der Carbonathärte), aus der Wasseranalyse. Richtwert ≥ 2,0 mmol/l, entspricht ≥ 5,6 dH° (Tab. 2 Zeile 11, S. 15); Tor REQ-09 prüft ihn. Liegt der Laborwert in dH° vor, in mmol/l umrechnen.
[EN] Acid capacity K_S4.3 of the irrigation water in mmol/l (equals carbonate hardness), from the water analysis. Guide value ≥ 2.0 mmol/l, corresponding to ≥ 5.6 dH° (Tab. 2 row 11, p. 15); gate REQ-09 checks it. If the laboratory reports dH°, convert to mmol/l.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.symbol = 'wasser_saurekapazitaet_mmol_l';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn „Chloridarm?“ = Ja und „Spurenelemente enthalten?“ = Ja; beide Felder müssen beantwortet sein. Grund: Als Düngemittel ist ein wasserlöslicher, chloridarmer Mehrnährstoffdünger mit ca. 15 % N, 10 % P₂O₅, 15 % K₂O und 2 % MgO vorzusehen, der zusätzlich die Spurennährelemente Fe, Cu, Mo, Mn, B und Zn enthält (§ 5.7, S. 15). Die Nährstoffanteile sind „ca.“-Werte und werden nur dokumentiert, nicht gesperrt.
[EN] Passes when ''Low-chloride?'' = Yes and ''Trace elements present?'' = Yes; both fields must be answered. Reason: the fertiliser must be a water-soluble, low-chloride compound fertiliser with about 15 % N, 10 % P₂O₅, 15 % K₂O and 2 % MgO that additionally contains the trace nutrients Fe, Cu, Mo, Mn, B and Zn (§ 5.7, p. 15). The nutrient shares are approximate values and are documented only, not blocked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.code = 'REQ-08';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn alle zehn Werte der Wasseranalyse die Richtwerte der Tab. 2 einhalten: Ammonium ≤ 0,5 mg/l; Eisen ≤ 0,2 mg/l; P_ges ≤ 0,03 mg/l; Härte ≥ 1,0 mmol/l; Leitfähigkeit ≤ 1000,0 µS/cm bei 20 °C; Mangan ≤ 0,05 mg/l; Nitrat ≤ 50,0 mg/l; ortho-Phosphat (P) ≤ 0,01 mg/l; pH 6,0 – 9,0; Säurekapazität K_S4,3 ≥ 2,0 mmol/l (Tab. 2, S. 15). Alle Felder ausfüllen, sonst bleibt das Tor rot. Grund: Die Wasserqualität muss Tab. 2 entsprechen; die Ausgangsbedingungen entsprechen den Füllwasser-Richtwerten der FLL-Schwimm- und Badeteichrichtlinien 2017 (§ 5.9, S. 15).
[EN] Passes when all ten values of the water analysis meet the Tab. 2 guide values: ammonium ≤ 0.5 mg/l; iron ≤ 0.2 mg/l; total P ≤ 0.03 mg/l; hardness ≥ 1.0 mmol/l; conductivity ≤ 1000.0 µS/cm at 20 °C; manganese ≤ 0.05 mg/l; nitrate ≤ 50.0 mg/l; ortho-phosphate (P) ≤ 0.01 mg/l; pH 6.0 – 9.0; acid capacity K_S4.3 ≥ 2.0 mmol/l (Tab. 2, p. 15). Fill all fields, otherwise the gate stays red. Reason: the water quality must meet Tab. 2; the initial conditions correspond to the fill-water guide values of the FLL swimming-pond guidelines 2017 (§ 5.9, p. 15).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-07' AND x.code = 'REQ-09';
UPDATE fields x SET description = 'Testpflanzenart: vorgeschrieben ist ausschließlich Phragmites australis (Schilf) (§ 5.8, S. 15; § 1, S. 7) — die einzige Option der Auswahl. Schilf bildet Rhizome (unterirdische Sprossausläufer), die Abdichtungen von innen und außen beschädigen können, und erwies sich in Voruntersuchungen als aggressivster Rhizombildner unter den Helophyten (§ 3.6, S. 9; § 1, S. 7). Tor REQ-10 auf FLLTP-RHZ-04 prüft die Art zusammen mit der Pflanzenzahl; Beschaffung durch das Prüfinstitut (§ 11, S. 24).
[EN] Test plant species: only Phragmites australis (common reed) is prescribed (§ 5.8, p. 15; § 1, p. 7) — the single option of the selection. Reed forms rhizomes (underground runners) that can damage sealings from inside and outside and proved the most aggressive rhizome former among the helophytes in preliminary studies (§ 3.6, p. 9; § 1, p. 7). Gate REQ-10 on FLLTP-RHZ-04 checks the species together with the plant count; procured by the test institute (§ 11, p. 24).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-08' AND x.symbol = 'testpflanze_art';
UPDATE fields x SET description = 'Containergröße der gelieferten Schilfpflanzen laut Lieferschein. Vorgeschrieben: Phragmites australis im 9 × 9 Container, in gleichmäßiger Pflanzenqualität (§ 5.8, S. 15). Freitext; kein Tor prüft das Format, Abweichungen vom 9 × 9 Container sind nicht vorgesehen.
[EN] Container size of the delivered reed plants per delivery note. Prescribed: Phragmites australis in a 9 × 9 container, of uniform plant quality (§ 5.8, p. 15). Free text; no gate checks the format, deviations from the 9 × 9 container are not provided for.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-08' AND x.symbol = 'testpflanze_container_format';
UPDATE fields x SET description = 'Nur bei nicht bahnenförmigen Abdichtungen (Flüssigabdichtung, Gussasphalt, GUP-Beschichtung): Zeit in Stunden zwischen den beiden Arbeitsschritten, in denen jedes Prüfmuster eingebaut wird, sodass in der Mitte des Gefäßes eine durchgehende Arbeitsunterbrechungsfuge entsteht; mindestens 12 Stunden (§ 7.1, S. 17). Aus dem Einbauprotokoll übernehmen; auch das zweite Prüfmuster ist so auszuführen. Tor REQ-12 prüft ≥ 12 h; bei bahnenartigen Abdichtungen ist das Feld ohne Bedeutung.
[EN] Non-sheet sealings only (liquid sealing, mastic asphalt, GUP coating): time in hours between the two work steps in which each specimen is installed, so that a continuous work joint results in the middle of the vessel; at least 12 hours (§ 7.1, p. 17). Take it from the installation record; the second specimen must be made the same way. Gate REQ-12 checks ≥ 12 h; for sheet-type sealings the field has no effect.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'arbeitsfuge_zeitabstand_h';
UPDATE fields x SET description = 'Bei bahnenartigen Abdichtungen: Zahl der Boden-Eck-Nähte am ersten Prüfmuster; vorgeschrieben sind zwei (§ 7.1, S. 17; Abb. 2, S. 18 — Maße für Gefäße 800 × 800 × 250 mm). Die Nähte werden am Untersuchungsort in Verantwortung des Auftraggebers fachtechnisch hergestellt (§ 7.1, S. 17). Tor REQ-11 prüft ≥ 2.
[EN] Sheet-type sealings: number of floor-corner seams on the first specimen; two are prescribed (§ 7.1, p. 17; Fig. 2, p. 18 — dimensions for 800 × 800 × 250 mm vessels). The seams are made professionally on site under the client''s responsibility (§ 7.1, p. 17). Gate REQ-11 checks ≥ 2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'naht_anzahl_boden_eck';
UPDATE fields x SET description = 'Bei bahnenartigen Abdichtungen: Zahl der Längsnähte am zweiten Prüfmuster, das um 45° versetzt auf der unteren Vegetationstragschicht liegt; vorgeschrieben sind zwei Längsnähte, die Ecken dieses Prüfmusters werden gefaltet (§ 7.1, S. 17; Abb. 3, S. 18 — 850 × 850 mm für Gefäße 800 × 800 × 250 mm). Tor REQ-11 prüft ≥ 2.
[EN] Sheet-type sealings: number of longitudinal seams on the second specimen, which lies rotated 45° on the lower substrate layer; two longitudinal seams are prescribed, the corners of this specimen are folded (§ 7.1, p. 17; Fig. 3, p. 18 — 850 × 850 mm for 800 × 800 × 250 mm vessels). Gate REQ-11 checks ≥ 2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'naht_anzahl_laengs_2_pruefmuster';
UPDATE fields x SET description = 'Bei bahnenartigen Abdichtungen: Zahl der T-Nähte am ersten Prüfmuster; vorgeschrieben ist eine mittig verlaufende T-Naht (§ 7.1, S. 17; Abb. 2, S. 18). Tor REQ-11 prüft ≥ 1.
[EN] Sheet-type sealings: number of T-seams on the first specimen; one centrally running T-seam is prescribed (§ 7.1, p. 17; Fig. 2, p. 18). Gate REQ-11 checks ≥ 1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'naht_anzahl_t_naht';
UPDATE fields x SET description = 'Bei bahnenartigen Abdichtungen: Zahl der Wand-Eck-Nähte am ersten Prüfmuster; vorgeschrieben sind vier (§ 7.1, S. 17; Abb. 2, S. 18). Die Prüfmuster müssen im eingebauten Zustand bis zur Gefäßoberkante reichen (§ 7.1, S. 17). Tor REQ-11 prüft ≥ 4.
[EN] Sheet-type sealings: number of wall-corner seams on the first specimen; four are prescribed (§ 7.1, p. 17; Fig. 2, p. 18). The installed specimens must reach the top edge of the vessel (§ 7.1, p. 17). Gate REQ-11 checks ≥ 4.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'naht_anzahl_wand_eck';
UPDATE fields x SET description = 'Verdrehung des zweiten Prüfmusters gegenüber dem ersten in Grad: Das zweite Prüfmuster wird um 45° versetzt zum ersten auf die untere Vegetationstragschicht eingebaut (§ 7.1, S. 17; Abb. 4, S. 19). Die Richtlinie schreibt den Versatz von 45° für alle Abdichtungen vor (§ 7.1, S. 17); Tor REQ-11 prüft ihn nur bei bahnenartigen Abdichtungen, bei nicht bahnenförmigen ist er dennoch einzuhalten und einzutragen.
[EN] Rotation of the second specimen relative to the first in degrees: the second specimen is installed on the lower substrate layer rotated 45° to the first (§ 7.1, p. 17; Fig. 4, p. 19). The guideline prescribes the 45° offset for all sealings (§ 7.1, p. 17); gate REQ-11 checks it only for sheet-type sealings, for non-sheet sealings it must still be kept and entered.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'pruefmuster_2_versatz_grad';
UPDATE fields x SET description = 'Durchmesser der Standrohre in mm: Ø 50 mm, Länge 200 mm, aus pflanzenverträglichem Werkstoff (z. B. PE) (§ 3.5, S. 9; Abb. 5, S. 19). Je Gefäß zwei Rohre: das erste auf der unteren Vegetationstragschicht nahe der Gefäßwand, das zweite innerhalb des zweiten Prüfmusters (§ 7.1, S. 17); im Kontrollgefäß nahe der Gefäßwand (§ 7.2, S. 19). Sie dienen der Kontrolle von Wasserstand und Wasserqualität (§ 3.5). Tor REQ-25 verlangt genau 50 mm.
[EN] Diameter of the standpipes in mm: Ø 50 mm, length 200 mm, of a plant-compatible material (e.g. PE) (§ 3.5, p. 9; Fig. 5, p. 19). Two pipes per vessel: the first on the lower substrate layer near the vessel wall, the second inside the second specimen (§ 7.1, p. 17); in the control vessel near the vessel wall (§ 7.2, p. 19). They serve to control water level and water quality (§ 3.5). Gate REQ-25 requires exactly 50 mm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'standrohr_durchmesser_mm';
UPDATE fields x SET description = 'Dicke der oberen Vegetationstragschicht in mm, beim Einbau gemessen: Sie wird nach dem zweiten Prüfmuster und dem zweiten Standrohr in einer Schichtdicke von (150 ±5) mm eingebaut, bei Gefäßen 800 × 800 mm ca. 100 l Substrat (§ 7.1, S. 17); im Kontrollgefäß ebenso (150 ±5) mm (§ 7.2, S. 19; Abb. 5). Tor REQ-13 prüft 145 bis 155 mm; der Wert geht in die Gesamtdicke (FLLTP-RHZ-06 D1, Tor REQ-26) ein und wird nach FLLTP-RHZ-10 übernommen.
[EN] Thickness of the upper substrate layer in mm, measured at installation: it is placed after the second specimen and the second standpipe at a thickness of (150 ±5) mm, about 100 l of substrate for 800 × 800 mm vessels (§ 7.1, p. 17); likewise (150 ±5) mm in the control vessel (§ 7.2, p. 19; Fig. 5). Gate REQ-13 checks 145 to 155 mm; the value feeds the total thickness (FLLTP-RHZ-06 D1, gate REQ-26) and is carried into FLLTP-RHZ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'vts_obere_schicht_dicke_mm';
UPDATE fields x SET description = 'Dicke der unteren Vegetationstragschicht in mm, beim Einbau gemessen: Sie wird nach dem ersten Prüfmuster in einer Schichtdicke von (20 ±5) mm eingebaut, bei Gefäßen 800 × 800 mm ca. 12 l Substrat, und trägt das erste Standrohr und das zweite Prüfmuster (§ 7.1, S. 17); im Kontrollgefäß ebenso (20 ±5) mm (§ 7.2, S. 19). Tor REQ-13 prüft 15 bis 25 mm; der Wert geht in die Gesamtdicke (FLLTP-RHZ-06 D1, Tor REQ-26) ein und wird nach FLLTP-RHZ-10 übernommen.
[EN] Thickness of the lower substrate layer in mm, measured at installation: it is placed after the first specimen at a thickness of (20 ±5) mm, about 12 l of substrate for 800 × 800 mm vessels, and carries the first standpipe and the second specimen (§ 7.1, p. 17); likewise (20 ±5) mm in the control vessel (§ 7.2, p. 19). Gate REQ-13 checks 15 to 25 mm; the value feeds the total thickness (FLLTP-RHZ-06 D1, gate REQ-26) and is carried into FLLTP-RHZ-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'vts_untere_schicht_dicke_mm';
UPDATE fields x SET description = 'Zahl der Standrohre je Gefäß: zwei eingelassene Rohre (§ 3.5, S. 9) — eines auf der unteren Vegetationstragschicht nahe der Gefäßwand, eines innerhalb des zweiten Prüfmusters (§ 7.1, S. 17; Abb. 4 und 5, S. 19). Tor REQ-25 verlangt genau 2. Über die Rohre wird der Wasserstand (20 mm über bis 50 mm unter der Substratoberfläche) kontrolliert (§ 7.3, S. 20).
[EN] Number of standpipes per vessel: two embedded pipes (§ 3.5, p. 9) — one on the lower substrate layer near the vessel wall, one inside the second specimen (§ 7.1, p. 17; Figs. 4 and 5, p. 19). Gate REQ-25 requires exactly 2. The pipes are used to control the water level (20 mm above to 50 mm below the substrate surface) (§ 7.3, p. 20).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'standrohr_anzahl';
UPDATE fields x SET description = 'Länge der Standrohre in mm: vorgeschrieben 200 mm bei Ø 50 mm, aus pflanzenverträglichem Werkstoff wie PE (§ 3.5, S. 9). Aus Lieferschein oder Maßkontrolle übernehmen; Tor REQ-25 verlangt genau 200 mm. Beschaffung und Einbau durch das Prüfinstitut (§ 11, S. 24).
[EN] Length of the standpipes in mm: 200 mm prescribed at Ø 50 mm, of a plant-compatible material such as PE (§ 3.5, p. 9). Take it from the delivery note or a dimensional check; gate REQ-25 requires exactly 200 mm. Procured and installed by the test institute (§ 11, p. 24).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.symbol = 'standrohr_laenge_mm';
UPDATE compliance_requirements x SET description = 'Gilt nur, wenn „Bahnenartig?“ (FLLTP-RHZ-02) = Ja; bei nicht bahnenförmigen Abdichtungen ist das Tor automatisch erfüllt. Bei Bahnen erfüllt, wenn am ersten Prüfmuster mindestens vier Wand-Eck-Nähte, zwei Boden-Eck-Nähte und eine mittig verlaufende T-Naht ausgeführt sind, am zweiten Prüfmuster mindestens zwei Längsnähte, und der Versatz des zweiten Prüfmusters genau 45° beträgt (§ 7.1, S. 17; Abb. 2–4, S. 18–19). Alle fünf Felder ausfüllen. Grund: Die Nähte werden zum Prüfende getrennt von der Fläche auf ein- und durchgedrungene Rhizome ausgewertet (§ 8.2, S. 21).
[EN] Applies only when ''Sheet-type?'' (FLLTP-RHZ-02) = Yes; for non-sheet sealings the gate passes automatically. For sheets it passes when the first specimen has at least four wall-corner seams, two floor-corner seams and one centrally running T-seam, the second specimen at least two longitudinal seams, and the rotation of the second specimen is exactly 45° (§ 7.1, p. 17; Figs. 2–4, pp. 18–19). Fill all five fields. Reason: at the end of the test the seams are evaluated for rhizome ingress and penetration separately from the surface (§ 8.2, p. 21).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.code = 'REQ-11';
UPDATE compliance_requirements x SET description = 'Gilt nur, wenn „Bahnenartig?“ (FLLTP-RHZ-02) = Nein; bei Bahnen ist das Tor automatisch erfüllt. Bei Flüssigabdichtung, Gussasphalt oder GUP-Beschichtung erfüllt, wenn der eingetragene Zeitabstand der Arbeitsunterbrechungsfuge mindestens 12 Stunden beträgt. Grund: Nicht bahnenförmige Abdichtungen werden in zwei Arbeitsschritten eingebaut, wobei in der Mitte des Gefäßes eine durchgehende Arbeitsunterbrechungsfuge anzuordnen ist; der Zeitabstand zwischen den beiden Arbeitsschritten muss mindestens 12 Stunden betragen; das zweite Prüfmuster wird ebenso ausgeführt (§ 7.1, S. 17).
[EN] Applies only when ''Sheet-type?'' (FLLTP-RHZ-02) = No; for sheets the gate passes automatically. For liquid sealing, mastic asphalt or GUP coating it passes when the entered interval of the work joint is at least 12 hours. Reason: non-sheet sealings are installed in two work steps with a continuous work joint arranged in the middle of the vessel; the interval between the two work steps must be at least 12 hours; the second specimen is made the same way (§ 7.1, p. 17).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.code = 'REQ-12';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn die untere Vegetationstragschicht 15 bis 25 mm dick ist, also (20 ±5) mm, und die obere 145 bis 155 mm, also (150 ±5) mm (§ 7.1, S. 17); beide Dicken beim Einbau messen und eintragen, sonst bleibt das Tor rot. Dieselben Dicken gelten für die Kontrollgefäße (§ 7.2, S. 19). Grund: Die untere Schicht trennt die beiden Prüfmuster, die obere trägt die Bepflanzung; zusammen ergeben sie die geforderten (170 ±10) mm (§ 5.6, S. 14), die Tor REQ-26 auf FLLTP-RHZ-06 prüft.
[EN] Passes when the lower substrate layer is 15 to 25 mm thick, i.e. (20 ±5) mm, and the upper 145 to 155 mm, i.e. (150 ±5) mm (§ 7.1, p. 17); measure and enter both thicknesses at installation, otherwise the gate stays red. The same thicknesses apply to the control vessels (§ 7.2, p. 19). Reason: the lower layer separates the two specimens, the upper carries the planting; together they give the required (170 ±10) mm (§ 5.6, p. 14) checked by gate REQ-26 on FLLTP-RHZ-06.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.code = 'REQ-13';
UPDATE compliance_requirements x SET description = 'Erfüllt, wenn je Gefäß genau zwei Standrohre mit Ø 50 mm und 200 mm Länge eingetragen sind; alle drei Felder (Anzahl, Durchmesser, Länge) müssen ausgefüllt sein. Grund: Durch zwei eingelassene Rohre (Ø 50 mm, Länge 200 mm) aus pflanzenverträglichen Werkstoffen (z. B. PE) wird in der Vegetationstragschicht die Kontrolle des Wasserstands und der Wasserqualität sichergestellt (§ 3.5, S. 9; Abb. 5, S. 19); der Wasserstand ist mittels Standrohr zwischen 20 mm über und 50 mm unter der Substratoberfläche zu halten (§ 7.3, S. 20).
[EN] Passes when exactly two standpipes with Ø 50 mm and 200 mm length are entered per vessel; all three fields (number, diameter, length) must be filled. Reason: two embedded pipes (Ø 50 mm, length 200 mm) of plant-compatible materials (e.g. PE) ensure control of water level and water quality in the substrate (§ 3.5, p. 9; Fig. 5, p. 19); the water level is to be kept by means of the standpipe between 20 mm above and 50 mm below the substrate surface (§ 7.3, p. 20).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-09' AND x.code = 'REQ-25';
UPDATE fields x SET description = 'Datum, an dem die drei Kontrollgefäße fertig vorbereitet wurden: untere Vegetationstragschicht, Standrohr, obere Vegetationstragschicht – ohne Widerlager und ohne Abdichtung (§ 7.2). Die Kontrollgefäße sind wasserdicht und ohne Wasserablauf auszuführen (§ 5.2). Reines Protokolldatum, keine Prüfung.
[EN] Date on which the three control vessels were fully prepared: lower substrate layer, standpipe, upper substrate layer – without abutment and without liner (§ 7.2). Control vessels are watertight and have no drain (§ 5.2). Log date only, no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-10' AND x.symbol = 'kontroll_einbau_datum';
UPDATE fields x SET description = 'Kurzbeschreibung, wie die Vegetationstragschicht in die Kontrollgefäße eingebracht wurde: untere Schicht (20 ±5) mm, danach Standrohr in Nähe der Gefäßwand, dann obere Schicht (150 ±5) mm (§ 7.2). Substrat ist gewaschener Sand 0–4 mm nach Tab. 1 (§ 5.6), derselbe wie in den Prüfgefäßen. Freitext für den Prüfbericht.
[EN] Short description of how the substrate was placed in the control vessels: lower layer (20 ±5) mm, then the standpipe near the vessel wall, then the upper layer (150 ±5) mm (§ 7.2). The substrate is washed sand 0–4 mm per Tab. 1 (§ 5.6), the same as in the test vessels. Free text for the report.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-10' AND x.symbol = 'kontroll_vts_einbau_methode';
UPDATE fields x SET description = 'Gemessene Dicke der unteren Vegetationstragschicht in den Kontrollgefäßen. Vorgabe (20 ±5) mm, also höchstens 5 mm Abweichung (§ 7.2) – gleiche Dicke wie die untere Schicht der Prüfgefäße (§ 7.1). Wert in mm aus der Einbaumessung eintragen.
[EN] Measured thickness of the lower substrate layer in the control vessels. Required (20 ±5) mm, i.e. at most 5 mm deviation (§ 7.2) – the same as the lower layer of the test vessels (§ 7.1). Enter the installation measurement in mm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-10' AND x.symbol = 'kontroll_vts_dicke_unten_mm';
UPDATE fields x SET description = 'Gemessene Dicke der oberen Vegetationstragschicht in den Kontrollgefäßen, eingebaut nach dem Standrohr. Vorgabe (150 ±5) mm (§ 7.2); zusammen mit der unteren Schicht ergibt sich die geforderte Gesamtdicke von (170 ±10) mm, ca. 110 l Substrat je 800 × 800-mm-Gefäß (§ 5.6).
[EN] Measured thickness of the upper substrate layer in the control vessels, placed after the standpipe. Required (150 ±5) mm (§ 7.2); with the lower layer this gives the required total of (170 ±10) mm, about 110 l of substrate per 800 × 800 mm vessel (§ 5.6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-10' AND x.symbol = 'kontroll_vts_dicke_oben_mm';
UPDATE fields x SET description = 'Bestätigung, dass in jedem Kontrollgefäß nach der unteren Schicht ein Standrohr in Nähe der Gefäßwand gesetzt wurde (§ 7.2). Standrohre sind Rohre Ø 50 mm, Länge 200 mm aus pflanzenverträglichem Werkstoff (z. B. PE), über die Wasserstand und Wasserqualität kontrolliert werden (§ 3.5). Ohne Standrohr ist der Wasserstand nach § 7.3 nicht kontrollierbar.
[EN] Confirm that in each control vessel a standpipe was set near the vessel wall after the lower layer (§ 7.2). Standpipes are tubes Ø 50 mm, 200 mm long, of plant-compatible material (e.g. PE) through which water level and water quality are checked (§ 3.5). Without a standpipe the water level per § 7.3 cannot be controlled.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-10' AND x.symbol = 'kontroll_standrohr_eingebaut';
UPDATE fields x SET description = 'Anzahl Schilfpflanzen (Phragmites australis) je Gefäß. Vorgabe: 8 Pflanzen je Gefäß von 800 × 800 mm (§ 5.8, § 7.1), Anordnung nach Abb. 4. Bei größeren Gefäßen ist die Pflanzdichte an die Gefäßfläche anzupassen (§ 5.2). Gilt für Prüf- und Kontrollgefäße gleichermaßen (§ 7.2) und wird in den Pflege- und Auswertungsblättern wiederverwendet.
[EN] Number of reed plants (Phragmites australis) per vessel. Required: 8 plants per 800 × 800 mm vessel (§ 5.8, § 7.1), arranged per Fig. 4. For larger vessels the planting density is scaled to the vessel area (§ 5.2). Applies equally to test and control vessels (§ 7.2) and is reused by the care and evaluation sheets.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-11' AND x.symbol = 'pflanzdichte_pro_gefaess';
UPDATE fields x SET description = 'Datum der Bepflanzung aller 8 Prüf- und 3 Kontrollgefäße. Die erste Düngergabe erfolgt unmittelbar nach der Bepflanzung, Pflanzenersatz ist nur in den ersten drei Monaten zulässig (§ 7.3). Bezugsdatum für die Auswertungen nach 6, 12, 18 und 24 Monaten (§ 3.7) der 2-jährigen Prüfung (§ 4).
[EN] Date of planting all 8 test and 3 control vessels. The first fertiliser dose is given immediately after planting; replacing plants is allowed only in the first three months (§ 7.3). Reference date for the evaluations after 6, 12, 18 and 24 months (§ 3.7) of the 2-year test (§ 4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-11' AND x.symbol = 'bepflanzung_datum';
UPDATE fields x SET description = 'Beschreibung, wie gepflanzt wurde: Containerpflanzen 9 × 9 (§ 5.8) in die obere Vegetationstragschicht, Lage der Pflanzen und Standrohre nach Abb. 4 (§ 7.1); Kontrollgefäße analog zu den Prüfgefäßen (§ 7.2). Die 8 Prüf- und 3 Kontrollgefäße sind im Gewächshaus nach Zufallsverteilung mit allseitig mindestens 0,4 m Abstand aufzustellen (§ 7.1).
[EN] Describe how planting was done: 9 × 9 container plants (§ 5.8) set into the upper substrate layer, plant and standpipe positions per Fig. 4 (§ 7.1); control vessels planted like the test vessels (§ 7.2). The 8 test and 3 control vessels are arranged randomly in the greenhouse with at least 0.4 m clearance on all sides (§ 7.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-11' AND x.symbol = 'pflanzung_methode';
UPDATE fields x SET description = 'Zustand der Testpflanzen bei der Pflanzung: Phragmites australis (Schilf) im 9 × 9 Container, auf gleichmäßige Pflanzenqualität ist zu achten (§ 5.8). Auffälligkeiten (ungleiche Größe, Schäden, Verfärbungen) hier notieren – Pflanzenschäden sind während der Prüfung gesondert zu erfassen (§ 8.1).
[EN] Condition of the test plants at planting: Phragmites australis (reed) in 9 × 9 containers, with uniform plant quality to be ensured (§ 5.8). Note anomalies here (uneven size, damage, discolouration) – plant damage during the test is recorded separately (§ 8.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-11' AND x.symbol = 'pflanzen_initial_zustand';
UPDATE fields x SET description = 'Gesamtzahl der gesetzten Pflanzen = Pflanzen je Gefäß × Anzahl Gefäße. Je Prüfung sind 8 Prüfgefäße mit Abdichtung und 3 Kontrollgefäße ohne Abdichtung vorgesehen (§ 4, § 5.2), je 800 × 800-mm-Gefäß 8 Pflanzen (§ 5.8). Nachgepflanzte Ersatzpflanzen (nur in den ersten drei Monaten, § 7.3) im Pflegeprotokoll vermerken.
[EN] Total number of plants set = plants per vessel × number of vessels. Each test uses 8 test vessels with liner and 3 control vessels without liner (§ 4, § 5.2), with 8 plants per 800 × 800 mm vessel (§ 5.8). Replacement plants (only in the first three months, § 7.3) are noted in the care log.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-11' AND x.symbol = 'anzahl_pflanzen_total';
UPDATE fields x SET description = 'Düngermenge je Gabe und Gefäß in g. Vorgabe: 5 g Düngemittel je 800 × 800-mm-Gefäß, gelöst in 20 l Wasser, gleichmäßig über die Vegetationstragschicht verteilt; erste Gabe unmittelbar nach der Bepflanzung (§ 7.3). Düngemittel nach § 5.7: wasserlöslich, chloridarm, ca. 15 % N, 10 % P₂O₅, 15 % K₂O, 2 % MgO mit Spurennährelementen. Bei größeren Gefäßen mit dem Skalierungsfaktor aus Blatt 05 anpassen (§ 5.2); Tor REQ-14 verlangt ≥ 5 g × Faktor.
[EN] Fertiliser quantity per dose and vessel in g. Required: 5 g of fertiliser per 800 × 800 mm vessel, dissolved in 20 l of water and spread evenly over the substrate; first dose immediately after planting (§ 7.3). Fertiliser per § 5.7: water-soluble, low in chloride, about 15 % N, 10 % P₂O₅, 15 % K₂O, 2 % MgO with trace elements. For larger vessels scale with the factor from sheet 05 (§ 5.2); gate REQ-14 requires ≥ 5 g × factor.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-12' AND x.symbol = 'duenger_gabe_g';
UPDATE fields x SET description = 'Abstand zwischen den Düngergaben in Monaten. Die Düngung erfolgt in monatlichem Abstand (§ 7.3) – also 1 eintragen. Tor REQ-14 verlangt genau 1; ein längeres Intervall wird nicht akzeptiert.
[EN] Interval between fertiliser doses in months. Fertilising is done at monthly intervals (§ 7.3) – enter 1. Gate REQ-14 requires exactly 1; a longer interval is not accepted.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-12' AND x.symbol = 'duenger_intervall_monate';
UPDATE fields x SET description = 'Wassermenge in l, in der die Düngergabe gelöst wird. Vorgabe: 20 l je Gabe und 800 × 800-mm-Gefäß (§ 7.3); bei größeren Gefäßen mit dem Skalierungsfaktor aus Blatt 05 anpassen (§ 5.2). Tor REQ-14 verlangt ≥ 20 l × Faktor.
[EN] Volume of water in l in which the fertiliser dose is dissolved. Required: 20 l per dose and 800 × 800 mm vessel (§ 7.3); for larger vessels scale with the factor from sheet 05 (§ 5.2). Gate REQ-14 requires ≥ 20 l × factor.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-12' AND x.symbol = 'duenger_loesung_l';
UPDATE fields x SET description = 'Zeitraum ab Bepflanzung in Monaten, in dem abgestorbene Pflanzen ersetzt wurden. Abgestorbene Pflanzen sind zu ersetzen, jedoch nur während der ersten drei Monate, um Wurzeln und Rhizome der verbleibenden Pflanzen nicht zu stören (§ 7.3). Tor REQ-14 verlangt ≤ 3. Wird danach keine ausreichende Wuchsleistung erreicht, ist die Prüfung abzubrechen (§ 7.3, § 3.12).
[EN] Period after planting in months during which dead plants were replaced. Dead plants must be replaced, but only during the first three months so that the roots and rhizomes of the remaining plants are not disturbed (§ 7.3). Gate REQ-14 requires ≤ 3. If growth remains insufficient afterwards, the test must be aborted (§ 7.3, § 3.12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-12' AND x.symbol = 'ersatz_pflanzen_periode_mon';
UPDATE fields x SET description = 'Angabe, ob ein Schnitt der Halme im grünen Zustand bei der Pflege (§ 7.3) zugelassen wurde. Ein Schnitt der Halme im grünen Zustand ist nicht zulässig; nur über den Winter abgestorbene Triebe werden im Frühjahr durch oberflächennahen Schnitt entfernt (§ 7.3). Für Tor REQ-14 muss hier „nein“ stehen.
[EN] State whether cutting stalks while green was permitted in the plant care (§ 7.3). Cutting stalks while green is not permitted; only shoots that died over winter are removed in spring by a cut close to the surface (§ 7.3). Gate REQ-14 requires ''no'' here.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-12' AND x.symbol = 'halmschnitt_im_gruenen_zulaessig';
UPDATE fields x SET description = 'Oberer Grenzwert des eingehaltenen Wasserstands über der Oberfläche der Vegetationstragschicht in mm. Vorgabe: höchstens 20 mm über der Oberfläche; Kontrolle über das Standrohr (§ 7.3, § 3.5). Tor REQ-14 verlangt den Wert 20.
[EN] Upper limit of the maintained water level above the substrate surface in mm. Required: at most 20 mm above the surface; checked via the standpipe (§ 7.3, § 3.5). Gate REQ-14 requires the value 20.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-12' AND x.symbol = 'wasserstand_max_ueber_vts_mm';
UPDATE fields x SET description = 'Unterer Grenzwert des eingehaltenen Wasserstands, als Tiefe unter der Oberfläche der Vegetationstragschicht in mm. Vorgabe: höchstens 50 mm unter der Oberfläche; Kontrolle über das Standrohr (§ 7.3, § 3.5). Tor REQ-14 verlangt den Wert 50.
[EN] Lower limit of the maintained water level, as depth below the substrate surface in mm. Required: at most 50 mm below the surface; checked via the standpipe (§ 7.3, § 3.5). Gate REQ-14 requires the value 50.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-12' AND x.symbol = 'wasserstand_min_unter_vts_mm';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die Pflege nach § 7.3 protokolliert ist: Wasserstand zwischen 20 mm über und 50 mm unter der Substratoberfläche (20 und 50 eintragen), Düngung monatlich (Intervall 1) mit mindestens 5 g in mindestens 20 l je 800 × 800-mm-Gefäß – bei größeren Gefäßen mit dem Skalierungsfaktor aus Blatt 05 vervielfacht (§ 5.2) –, Pflanzenersatz höchstens in den ersten 3 Monaten, kein Halmschnitt im grünen Zustand. Alle sieben Felder dieses Blatts und der Skalierungsfaktor müssen gefüllt sein, sonst ist das Tor nicht entscheidbar. Fremdwuchs, Algen und abgestorbene Pflanzenteile sind zu entfernen; Pflanzenschutz bei starkem Befall (§ 7.3).
[EN] Passes when care per § 7.3 is logged: water level between 20 mm above and 50 mm below the substrate surface (enter 20 and 50), monthly fertilising (interval 1) with at least 5 g in at least 20 l per 800 × 800 mm vessel – multiplied by the scaling factor from sheet 05 for larger vessels (§ 5.2) –, plant replacement only within the first 3 months, no cutting of green stalks. All seven fields of this sheet and the scaling factor must be filled, otherwise the gate cannot be decided. Weeds, algae and dead plant parts must be removed; plant protection in case of heavy infestation (§ 7.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-12' AND x.code = 'REQ-14';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die 2. Zwischenauswertung nach 12 Monaten eine mittlere Bestandsdichte der 8 Prüfgefäße von mindestens 120 Halmen je Gefäß und zugleich mindestens 80 % der Bestandsdichte der Kontrollgefäße zeigt (§ 3.7). Zu entscheiden braucht das Tor die Felder „Ø Bestandsdichte Prüfgefäße 12 Mon.“ und „Relative Dichte 12 Mon.“ aus Blatt 14 – dieses Blatt kann daher erst nach der 12-Monats-Zählung freigegeben werden. Die Halmanzahl ist halbjährlich in allen Gefäßen zu erfassen (§ 8.1); ohne ausreichende Wuchsleistung ist die Prüfung abzubrechen (§ 3.12).
[EN] Passes when the 2nd interim evaluation after 12 months shows a mean density of the 8 test vessels of at least 120 stalks per vessel and at the same time at least 80 % of the control vessels'' density (§ 3.7). To decide, the gate needs the fields ''Avg plant density test 12m'' and ''Relative density 12 mon.'' from sheet 14 – so this sheet can only be approved after the 12-month count. Stalk counts are taken every six months in all vessels (§ 8.1); without sufficient growth the test must be aborted (§ 3.12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-12' AND x.code = 'REQ-16';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die 3. Zwischenauswertung nach 18 Monaten eine mittlere Bestandsdichte der 8 Prüfgefäße von mindestens 160 Halmen je Gefäß und zugleich mindestens 80 % der Bestandsdichte der Kontrollgefäße zeigt (§ 3.7). Zu entscheiden braucht das Tor die Felder „Ø Bestandsdichte Prüfgefäße 18 Mon.“ und „Relative Dichte 18 Mon.“ aus Blatt 15. Halmzählung halbjährlich (§ 8.1); bei unzureichender Wuchsleistung ist die Prüfung abzubrechen (§ 3.12).
[EN] Passes when the 3rd interim evaluation after 18 months shows a mean density of the 8 test vessels of at least 160 stalks per vessel and at the same time at least 80 % of the control vessels'' density (§ 3.7). To decide, the gate needs the fields ''Avg plant density test 18m'' and ''Relative density 18 mon.'' from sheet 15. Stalk counts every six months (§ 8.1); with insufficient growth the test must be aborted (§ 3.12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-12' AND x.code = 'REQ-17';
UPDATE fields x SET description = 'Mittlere Halmanzahl der 3 Kontrollgefäße bei der 6-Monats-Auswertung, in Halmen je Gefäß. Wird aus K1–K3 berechnet (EQ-2) bzw. entspricht der Zeile „Ø K 1 – K 3“ in Tab. 2 des Musterberichts. Dient als Bezugswert: Die Bestandsdichte der Prüfgefäße muss mindestens 80 % dieses Werts erreichen, damit eine Beeinträchtigung durch pflanzenschädigende Stoffe der Abdichtung ausgeschlossen werden kann (§ 3.7).
[EN] Mean stalk count of the 3 control vessels at the 6-month evaluation, in stalks per vessel. Computed from K1–K3 (EQ-2) or equal to the row ''Ø K 1 – K 3'' in Tab. 2 of the model report. Serves as reference: the test vessels'' density must reach at least 80 % of this value so that an impairment by plant-damaging substances of the liner can be ruled out (§ 3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'bestandsdichte_k_avg';
UPDATE fields x SET description = 'Mittlere Halmanzahl der 8 Prüfgefäße nach 6 Monaten, in Halmen je Gefäß. Anforderung der 1. Zwischenauswertung: mindestens 80 Halme je Gefäß (§ 3.7; Tab. 1 Musterbericht „Ø Mindestanzahl ≥ 80“). Tor REQ-15 liest dieses eingetragene Feld – den Wert gleich dem berechneten Mittel aus P1–P8 (EQ-1) eintragen.
[EN] Mean stalk count of the 8 test vessels after 6 months, in stalks per vessel. Requirement of the 1st interim evaluation: at least 80 stalks per vessel (§ 3.7; model report Tab. 1 ''Ø Mindestanzahl ≥ 80''). Gate REQ-15 reads this typed field – enter the value equal to the computed mean of P1–P8 (EQ-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'bestandsdichte_p_avg_6mon';
UPDATE fields x SET description = 'Relative Bestandsdichte nach 6 Monaten: Mittel der Prüfgefäße bezogen auf das Mittel der Kontrollgefäße, × 100, in %. Berechnet aus EQ-1 und EQ-2 (EQ-3); im Musterbericht Tab. 3 „Ø P1–P8 / Ø K1–K3 × 100“ mit Sollwert ≥ 80 %. Die Prüfgefäße müssen mindestens 80 % der Kontrollgefäße erreichen (§ 3.7); Tor REQ-15.
[EN] Relative density after 6 months: mean of the test vessels relative to the mean of the control vessels, × 100, in %. Computed from EQ-1 and EQ-2 (EQ-3); model report Tab. 3 ''Ø P1–P8 / Ø K1–K3 × 100'' with target ≥ 80 %. The test vessels must reach at least 80 % of the control vessels (§ 3.7); gate REQ-15.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'dichte_relativ_prozent';
UPDATE fields x SET description = 'Ergebnis der 1. Zwischenauswertung. „bestanden“, wenn das Mittel der Prüfgefäße ≥ 80 Halme je Gefäß und ≥ 80 % der Kontrollgefäße beträgt (§ 3.7); „nicht bestanden“ sonst – dann ist die Prüfung abzubrechen (§ 3.12, § 8.1). Ausreichende Wuchsleistung im gesamten Prüfungsverlauf ist Voraussetzung für das Ergebnis „rhizomfest“ (§ 3.11).
[EN] Result of the 1st interim evaluation. ''pass'' when the test vessels'' mean is ≥ 80 stalks per vessel and ≥ 80 % of the control vessels (§ 3.7); ''fail'' otherwise – then the test must be aborted (§ 3.12, § 8.1). Sufficient growth throughout the test is a prerequisite for the verdict ''rhizome resistant'' (§ 3.11).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'wuchsleistung_ausreichend';
UPDATE fields x SET description = 'Gezählte Halme im Prüfgefäß P 1 bei der 6-Monats-Auswertung. Die Wüchsigkeit wird halbjährlich in allen Prüf- und Kontrollgefäßen durch Erfassen der Halmanzahl festgehalten (§ 8.1); Eintrag wie in Tab. 1 des Musterberichts (Anzahl Halme je Gefäß). Eingang für EQ-1.
[EN] Counted stalks in test vessel P 1 at the 6-month evaluation. Vigour is recorded every six months in all test and control vessels by counting the stalks (§ 8.1); entry as in Tab. 1 of the model report (stalks per vessel). Input to EQ-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'P_1';
UPDATE fields x SET description = 'Gezählte Halme im Prüfgefäß P 2 bei der 6-Monats-Auswertung. Die Wüchsigkeit wird halbjährlich in allen Prüf- und Kontrollgefäßen durch Erfassen der Halmanzahl festgehalten (§ 8.1); Eintrag wie in Tab. 1 des Musterberichts. Eingang für EQ-1.
[EN] Counted stalks in test vessel P 2 at the 6-month evaluation. Vigour is recorded every six months in all test and control vessels by counting the stalks (§ 8.1); entry as in Tab. 1 of the model report. Input to EQ-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'P_2';
UPDATE fields x SET description = 'Gezählte Halme im Prüfgefäß P 3 bei der 6-Monats-Auswertung. Die Wüchsigkeit wird halbjährlich in allen Prüf- und Kontrollgefäßen durch Erfassen der Halmanzahl festgehalten (§ 8.1); Eintrag wie in Tab. 1 des Musterberichts. Eingang für EQ-1.
[EN] Counted stalks in test vessel P 3 at the 6-month evaluation. Vigour is recorded every six months in all test and control vessels by counting the stalks (§ 8.1); entry as in Tab. 1 of the model report. Input to EQ-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'P_3';
UPDATE fields x SET description = 'Gezählte Halme im Prüfgefäß P 4 bei der 6-Monats-Auswertung. Die Wüchsigkeit wird halbjährlich in allen Prüf- und Kontrollgefäßen durch Erfassen der Halmanzahl festgehalten (§ 8.1); Eintrag wie in Tab. 1 des Musterberichts. Eingang für EQ-1.
[EN] Counted stalks in test vessel P 4 at the 6-month evaluation. Vigour is recorded every six months in all test and control vessels by counting the stalks (§ 8.1); entry as in Tab. 1 of the model report. Input to EQ-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'P_4';
UPDATE fields x SET description = 'Gezählte Halme im Prüfgefäß P 5 bei der 6-Monats-Auswertung. Die Wüchsigkeit wird halbjährlich in allen Prüf- und Kontrollgefäßen durch Erfassen der Halmanzahl festgehalten (§ 8.1); Eintrag wie in Tab. 1 des Musterberichts. Eingang für EQ-1.
[EN] Counted stalks in test vessel P 5 at the 6-month evaluation. Vigour is recorded every six months in all test and control vessels by counting the stalks (§ 8.1); entry as in Tab. 1 of the model report. Input to EQ-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'P_5';
UPDATE fields x SET description = 'Gezählte Halme im Prüfgefäß P 6 bei der 6-Monats-Auswertung. Die Wüchsigkeit wird halbjährlich in allen Prüf- und Kontrollgefäßen durch Erfassen der Halmanzahl festgehalten (§ 8.1); Eintrag wie in Tab. 1 des Musterberichts. Eingang für EQ-1.
[EN] Counted stalks in test vessel P 6 at the 6-month evaluation. Vigour is recorded every six months in all test and control vessels by counting the stalks (§ 8.1); entry as in Tab. 1 of the model report. Input to EQ-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'P_6';
UPDATE fields x SET description = 'Gezählte Halme im Prüfgefäß P 7 bei der 6-Monats-Auswertung. Die Wüchsigkeit wird halbjährlich in allen Prüf- und Kontrollgefäßen durch Erfassen der Halmanzahl festgehalten (§ 8.1); Eintrag wie in Tab. 1 des Musterberichts. Eingang für EQ-1.
[EN] Counted stalks in test vessel P 7 at the 6-month evaluation. Vigour is recorded every six months in all test and control vessels by counting the stalks (§ 8.1); entry as in Tab. 1 of the model report. Input to EQ-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'P_7';
UPDATE fields x SET description = 'Gezählte Halme im Prüfgefäß P 8 bei der 6-Monats-Auswertung. Die Wüchsigkeit wird halbjährlich in allen Prüf- und Kontrollgefäßen durch Erfassen der Halmanzahl festgehalten (§ 8.1); Eintrag wie in Tab. 1 des Musterberichts. Eingang für EQ-1.
[EN] Counted stalks in test vessel P 8 at the 6-month evaluation. Vigour is recorded every six months in all test and control vessels by counting the stalks (§ 8.1); entry as in Tab. 1 of the model report. Input to EQ-1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'P_8';
UPDATE fields x SET description = 'Gezählte Halme im Kontrollgefäß K 1 (ohne Abdichtung) bei der 6-Monats-Auswertung; halbjährliche Erfassung der Halmanzahl (§ 8.1), Eintrag wie in Tab. 2 des Musterberichts. Eingang für EQ-2; die Kontrollgefäße liefern den Bezugswert für die 80-%-Regel (§ 3.7).
[EN] Counted stalks in control vessel K 1 (without liner) at the 6-month evaluation; stalk count taken every six months (§ 8.1), entry as in Tab. 2 of the model report. Input to EQ-2; the control vessels provide the reference for the 80 % rule (§ 3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'K_1';
UPDATE fields x SET description = 'Gezählte Halme im Kontrollgefäß K 2 (ohne Abdichtung) bei der 6-Monats-Auswertung; halbjährliche Erfassung der Halmanzahl (§ 8.1), Eintrag wie in Tab. 2 des Musterberichts. Eingang für EQ-2; die Kontrollgefäße liefern den Bezugswert für die 80-%-Regel (§ 3.7).
[EN] Counted stalks in control vessel K 2 (without liner) at the 6-month evaluation; stalk count taken every six months (§ 8.1), entry as in Tab. 2 of the model report. Input to EQ-2; the control vessels provide the reference for the 80 % rule (§ 3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'K_2';
UPDATE fields x SET description = 'Gezählte Halme im Kontrollgefäß K 3 (ohne Abdichtung) bei der 6-Monats-Auswertung; halbjährliche Erfassung der Halmanzahl (§ 8.1), Eintrag wie in Tab. 2 des Musterberichts. Eingang für EQ-2; die Kontrollgefäße liefern den Bezugswert für die 80-%-Regel (§ 3.7).
[EN] Counted stalks in control vessel K 3 (without liner) at the 6-month evaluation; stalk count taken every six months (§ 8.1), entry as in Tab. 2 of the model report. Input to EQ-2; the control vessels provide the reference for the 80 % rule (§ 3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'K_3';
UPDATE fields x SET description = 'Berechnetes Mittel der Halmanzahl über die 8 Prüfgefäße (EQ-1), in Halmen je Gefäß – Zeile „Ø P 1 – P 8“ in Tab. 1 des Musterberichts. Nach 6 Monaten sind mindestens 80 Halme je Gefäß gefordert (§ 3.7). Zähler der relativen Bestandsdichte (EQ-3); der Wert ist in das Feld „Ø Bestandsdichte Prüfgefäße 6 Mon.“ zu übernehmen, das Tor REQ-15 liest.
[EN] Computed mean stalk count over the 8 test vessels (EQ-1), in stalks per vessel – row ''Ø P 1 – P 8'' in Tab. 1 of the model report. After 6 months at least 80 stalks per vessel are required (§ 3.7). Numerator of the relative density (EQ-3); carry the value into the field ''Avg plant density test 6m'', which gate REQ-15 reads.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.symbol = 'bestandsdichte_p_avg';
UPDATE equations x SET description = 'Arithmetisches Mittel der Halmanzahl der 8 Prüfgefäße: Summe P1 bis P8 geteilt durch 8, Ergebnis in Halmen je Gefäß. Entspricht der Zeile „Ø P 1 – P 8“ in Tab. 1 des Musterberichts; die Zählung erfolgt halbjährlich (§ 8.1). Das Mittel wird mit den Mindestwerten 80 / 120 / 160 / 160 Halme je Gefäß nach 6 / 12 / 18 / 24 Monaten verglichen (§ 3.7) und geht als Zähler in EQ-3 ein.
[EN] Arithmetic mean of the stalk count of the 8 test vessels: sum of P1 to P8 divided by 8, result in stalks per vessel. Corresponds to the row ''Ø P 1 – P 8'' in Tab. 1 of the model report; counts are taken every six months (§ 8.1). The mean is compared with the minimums 80 / 120 / 160 / 160 stalks per vessel after 6 / 12 / 18 / 24 months (§ 3.7) and is the numerator of EQ-3.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.equation_number = 'EQ-1';
UPDATE equations x SET description = 'Arithmetisches Mittel der Halmanzahl der 3 Kontrollgefäße ohne Abdichtung: Summe K1 bis K3 geteilt durch 3, in Halmen je Gefäß. Entspricht der Zeile „Ø K 1 – K 3“ in Tab. 2 des Musterberichts. Das Mittel ist der Nenner der relativen Bestandsdichte (EQ-3); Prüf- und Kontrollgefäße müssen während der gesamten Prüfdauer ähnlich hohe Bestandsdichten aufweisen (§ 3.7).
[EN] Arithmetic mean of the stalk count of the 3 control vessels without liner: sum of K1 to K3 divided by 3, in stalks per vessel. Corresponds to the row ''Ø K 1 – K 3'' in Tab. 2 of the model report. The mean is the denominator of the relative density (EQ-3); test and control vessels must show similarly high densities throughout the test (§ 3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.equation_number = 'EQ-2';
UPDATE equations x SET description = 'Relative Bestandsdichte in %: Mittel der Prüfgefäße (EQ-1) geteilt durch Mittel der Kontrollgefäße (EQ-2), mal 100. So im Musterbericht Tab. 3 gedruckt („Ø P 1 – P 8 / Ø K 1 – K 3 × 100“, Sollwert ≥ 80 %). Die Prüfgefäße müssen mindestens 80 % der Kontrollgefäße erreichen, sonst ist eine Beeinträchtigung durch pflanzenschädigende Stoffe der Abdichtung zu vermuten (§ 3.7). Das Ergebnis liest Tor REQ-15; für 12, 18 und 24 Monate wird die relative Dichte auf den Blättern 14–16 eingetragen und von den Toren REQ-16 bis REQ-18 gelesen.
[EN] Relative density in %: mean of the test vessels (EQ-1) divided by the mean of the control vessels (EQ-2), times 100. Printed in the model report Tab. 3 (''Ø P 1 – P 8 / Ø K 1 – K 3 × 100'', target ≥ 80 %). The test vessels must reach at least 80 % of the control vessels, otherwise an impairment by plant-damaging substances of the liner is to be suspected (§ 3.7). The result is read by gate REQ-15; for 12, 18 and 24 months the relative density is entered on sheets 14–16 and read by gates REQ-16 to REQ-18.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.equation_number = 'EQ-3';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die 1. Zwischenauswertung nach 6 Monaten ein Mittel der 8 Prüfgefäße von mindestens 80 Halmen je Gefäß und zugleich mindestens 80 % der Bestandsdichte der Kontrollgefäße ergibt (§ 3.7). Dafür P1–P8 und K1–K3 eintragen (EQ-1 bis EQ-3) und das 6-Monats-Mittel in „Ø Bestandsdichte Prüfgefäße 6 Mon.“ übernehmen – das Tor liest dieses Feld und die relative Dichte. Die Halmanzahl ist halbjährlich in allen Gefäßen zu erfassen (§ 8.1); wird keine ausreichende Wuchsleistung erzielt, ist die Prüfung abzubrechen (§ 3.12).
[EN] Passes when the 1st interim evaluation after 6 months gives a mean of the 8 test vessels of at least 80 stalks per vessel and at the same time at least 80 % of the control vessels'' density (§ 3.7). Enter P1–P8 and K1–K3 (EQ-1 to EQ-3) and carry the 6-month mean into ''Avg plant density test 6m'' – the gate reads that field and the relative density. Stalks are counted every six months in all vessels (§ 8.1); if growth is insufficient the test must be aborted (§ 3.12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-13' AND x.code = 'REQ-15';
UPDATE fields x SET description = 'Mittlere Halmanzahl der 8 Prüfgefäße bei der 12-Monats-Zählung (§ 8.1), in Halmen je Gefäß – Spalte des 2. Termins in Tab. 1 des Musterberichts. Anforderung der 2. Zwischenauswertung: mindestens 120 Halme je Gefäß (§ 3.7). Wird von Tor REQ-16 (auf Blatt 12) gelesen.
[EN] Mean stalk count of the 8 test vessels at the 12-month count (§ 8.1), in stalks per vessel – column of the 2nd date in Tab. 1 of the model report. Requirement of the 2nd interim evaluation: at least 120 stalks per vessel (§ 3.7). Read by gate REQ-16 (on sheet 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-14' AND x.symbol = 'bestandsdichte_p_avg_12mon';
UPDATE fields x SET description = 'Mittlere Halmanzahl der 3 Kontrollgefäße bei der 12-Monats-Zählung, in Halmen je Gefäß (Zeile „Ø K 1 – K 3“, Tab. 2 Musterbericht). Bezugswert für die relative Dichte: Die Prüfgefäße müssen mindestens 80 % dieses Werts erreichen (§ 3.7).
[EN] Mean stalk count of the 3 control vessels at the 12-month count, in stalks per vessel (row ''Ø K 1 – K 3'', Tab. 2 of the model report). Reference for the relative density: the test vessels must reach at least 80 % of this value (§ 3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-14' AND x.symbol = 'kontrolle_p_avg_12mon';
UPDATE fields x SET description = 'Relative Bestandsdichte nach 12 Monaten in %: Mittel Prüfgefäße geteilt durch Mittel Kontrollgefäße, mal 100 (Musterbericht Tab. 3, Sollwert ≥ 80 %). Anforderung: mindestens 80 % (§ 3.7). Wird von Tor REQ-16 (auf Blatt 12) gelesen.
[EN] Relative density after 12 months in %: mean of test vessels divided by mean of control vessels, times 100 (model report Tab. 3, target ≥ 80 %). Requirement: at least 80 % (§ 3.7). Read by gate REQ-16 (on sheet 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-14' AND x.symbol = 'relativ_prozent_12mon';
UPDATE fields x SET description = 'Bestätigung, dass die 2. Zwischenauswertung bestanden ist: Mittel der Prüfgefäße ≥ 120 Halme je Gefäß und ≥ 80 % der Kontrollgefäße (§ 3.7). Ist die Wuchsleistung nicht ausreichend, ist die Prüfung abzubrechen (§ 3.12, § 8.1) und das Ergebnis in Blatt 18 als „vorzeitig abgebrochen“ zu führen.
[EN] Confirm that the 2nd interim evaluation is passed: test vessels'' mean ≥ 120 stalks per vessel and ≥ 80 % of the control vessels (§ 3.7). If growth is insufficient the test must be aborted (§ 3.12, § 8.1) and the verdict in sheet 18 recorded as ''terminated early''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-14' AND x.symbol = 'wuchsleistung_12mon_ausreichend';
UPDATE fields x SET description = 'Datum der 12-Monats-Zählung. Die Ausbreitung der Testpflanzen wird im Abstand von 6 Monaten erfasst (§ 3.7), die Halmanzahl halbjährlich in allen Prüf- und Kontrollgefäßen (§ 8.1). Während der Prüfung dürfen keine Zwischenergebnisse schriftlich bekannt gegeben werden (§ 9).
[EN] Date of the 12-month count. The spread of the test plants is recorded at 6-month intervals (§ 3.7), the stalk count every six months in all test and control vessels (§ 8.1). No interim results may be issued in writing during the test (§ 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-14' AND x.symbol = 'auswertungs_datum_12mon';
UPDATE fields x SET description = 'Mittlere Halmanzahl der 8 Prüfgefäße bei der 18-Monats-Zählung (§ 8.1), in Halmen je Gefäß – Spalte des 3. Termins in Tab. 1 des Musterberichts. Anforderung der 3. Zwischenauswertung: mindestens 160 Halme je Gefäß (§ 3.7). Wird von Tor REQ-17 (auf Blatt 12) gelesen.
[EN] Mean stalk count of the 8 test vessels at the 18-month count (§ 8.1), in stalks per vessel – column of the 3rd date in Tab. 1 of the model report. Requirement of the 3rd interim evaluation: at least 160 stalks per vessel (§ 3.7). Read by gate REQ-17 (on sheet 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-15' AND x.symbol = 'bestandsdichte_p_avg_18mon';
UPDATE fields x SET description = 'Mittlere Halmanzahl der 3 Kontrollgefäße bei der 18-Monats-Zählung, in Halmen je Gefäß (Zeile „Ø K 1 – K 3“, Tab. 2 Musterbericht). Bezugswert für die relative Dichte: Die Prüfgefäße müssen mindestens 80 % dieses Werts erreichen (§ 3.7).
[EN] Mean stalk count of the 3 control vessels at the 18-month count, in stalks per vessel (row ''Ø K 1 – K 3'', Tab. 2 of the model report). Reference for the relative density: the test vessels must reach at least 80 % of this value (§ 3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-15' AND x.symbol = 'kontrolle_p_avg_18mon';
UPDATE fields x SET description = 'Relative Bestandsdichte nach 18 Monaten in %: Mittel Prüfgefäße geteilt durch Mittel Kontrollgefäße, mal 100 (Musterbericht Tab. 3, Sollwert ≥ 80 %). Anforderung: mindestens 80 % (§ 3.7). Wird von Tor REQ-17 (auf Blatt 12) gelesen.
[EN] Relative density after 18 months in %: mean of test vessels divided by mean of control vessels, times 100 (model report Tab. 3, target ≥ 80 %). Requirement: at least 80 % (§ 3.7). Read by gate REQ-17 (on sheet 12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-15' AND x.symbol = 'relativ_prozent_18mon';
UPDATE fields x SET description = 'Bestätigung, dass die 3. Zwischenauswertung bestanden ist: Mittel der Prüfgefäße ≥ 160 Halme je Gefäß und ≥ 80 % der Kontrollgefäße (§ 3.7). Ist die Wuchsleistung nicht ausreichend, ist die Prüfung abzubrechen (§ 3.12, § 8.1) und das Ergebnis in Blatt 18 als „vorzeitig abgebrochen“ zu führen.
[EN] Confirm that the 3rd interim evaluation is passed: test vessels'' mean ≥ 160 stalks per vessel and ≥ 80 % of the control vessels (§ 3.7). If growth is insufficient the test must be aborted (§ 3.12, § 8.1) and the verdict in sheet 18 recorded as ''terminated early''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-15' AND x.symbol = 'wuchsleistung_18mon_ausreichend';
UPDATE fields x SET description = 'Datum der 18-Monats-Zählung. Die Ausbreitung der Testpflanzen wird im Abstand von 6 Monaten erfasst (§ 3.7), die Halmanzahl halbjährlich in allen Prüf- und Kontrollgefäßen (§ 8.1). Während der Prüfung dürfen keine Zwischenergebnisse schriftlich bekannt gegeben werden (§ 9).
[EN] Date of the 18-month count. The spread of the test plants is recorded at 6-month intervals (§ 3.7), the stalk count every six months in all test and control vessels (§ 8.1). No interim results may be issued in writing during the test (§ 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-15' AND x.symbol = 'auswertungs_datum_18mon';
UPDATE fields x SET description = 'Mittlere Halmanzahl der 8 Prüfgefäße bei der Endauswertung nach 24 Monaten, in Halmen je Gefäß – letzte Spalte in Tab. 1 des Musterberichts. Anforderung der Endauswertung: mindestens 160 Halme je Gefäß (§ 3.7). Die Wuchsleistung ist zum Ende der Prüfung abschließend zu erfassen (§ 8.2). Wird von Tor REQ-18 sowie den Blättern 18 und 21 gelesen.
[EN] Mean stalk count of the 8 test vessels at the final evaluation after 24 months, in stalks per vessel – last column in Tab. 1 of the model report. Requirement of the final evaluation: at least 160 stalks per vessel (§ 3.7). Growth is recorded conclusively at the end of the test (§ 8.2). Read by gate REQ-18 and by sheets 18 and 21.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-16' AND x.symbol = 'bestandsdichte_p_avg_24mon';
UPDATE fields x SET description = 'Mittlere Halmanzahl der 3 Kontrollgefäße bei der Endauswertung nach 24 Monaten, in Halmen je Gefäß (Zeile „Ø K 1 – K 3“, Tab. 2 Musterbericht). Bezugswert: Die Prüfgefäße müssen mindestens 80 % dieses Werts erreichen; Prüf- und Kontrollgefäße sollen über die gesamte Prüfdauer ähnlich hoch bestanden sein (§ 3.7).
[EN] Mean stalk count of the 3 control vessels at the final evaluation after 24 months, in stalks per vessel (row ''Ø K 1 – K 3'', Tab. 2 of the model report). Reference: the test vessels must reach at least 80 % of this value; test and control vessels must be similarly dense throughout the test (§ 3.7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-16' AND x.symbol = 'kontrolle_p_avg_24mon';
UPDATE fields x SET description = 'Relative Bestandsdichte bei der Endauswertung in %: Mittel Prüfgefäße geteilt durch Mittel Kontrollgefäße, mal 100 (Musterbericht Tab. 3, Sollwert ≥ 80 %). Anforderung: mindestens 80 % (§ 3.7). Wird von Tor REQ-18 gelesen.
[EN] Relative density at the final evaluation in %: mean of test vessels divided by mean of control vessels, times 100 (model report Tab. 3, target ≥ 80 %). Requirement: at least 80 % (§ 3.7). Read by gate REQ-18.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-16' AND x.symbol = 'relativ_prozent_24mon';
UPDATE fields x SET description = 'Bestätigung, dass die Endauswertung bestanden ist: Mittel der Prüfgefäße ≥ 160 Halme je Gefäß und ≥ 80 % der Kontrollgefäße (§ 3.7). Nur wenn die Pflanzen im gesamten Prüfungsverlauf eine ausreichende Wuchsleistung erbracht haben, kann das Produkt als rhizomfest gelten (§ 3.11); im Musterbericht wird dies als „geforderte Mindestwuchsleistung … erreicht“ ausgewiesen.
[EN] Confirm that the final evaluation is passed: test vessels'' mean ≥ 160 stalks per vessel and ≥ 80 % of the control vessels (§ 3.7). Only if the plants showed sufficient growth throughout the whole test can the product count as rhizome resistant (§ 3.11); the model report states this as ''required minimum growth … achieved''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-16' AND x.symbol = 'wuchsleistung_24mon_ausreichend';
UPDATE fields x SET description = 'Datum der Endauswertung nach Ablauf der 2-jährigen Prüfung (§ 4). Der Zeitpunkt der anstehenden Endauswertung ist dem Auftraggeber vorher mitzuteilen, um ihm eine Teilnahme zu ermöglichen (§ 8.2). An diesem Termin werden Halmanzahl erfasst, die Vegetationstragschicht entnommen und die Abdichtung auf Rhizome geprüft (§ 8.2, Blatt 17).
[EN] Date of the final evaluation at the end of the 2-year test (§ 4). The client must be informed of the date in advance so that they can attend (§ 8.2). On this date the stalks are counted, the substrate removed and the liner examined for rhizomes (§ 8.2, sheet 17).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-16' AND x.symbol = 'endauswertung_datum';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die Endauswertung nach 24 Monaten ein Mittel der 8 Prüfgefäße von mindestens 160 Halmen je Gefäß und zugleich mindestens 80 % der Bestandsdichte der Kontrollgefäße ergibt (§ 3.7). Dafür „Ø Bestandsdichte Prüfgefäße 24 Mon.“ und „Relative Dichte 24 Mon.“ eintragen (Kontrollmittel wird für die relative Dichte gebraucht). Ausreichende Wuchsleistung im gesamten Prüfungsverlauf ist Voraussetzung für das Ergebnis „rhizomfest“ (§ 3.11); die Wuchsleistung ist zum Ende der Prüfung abschließend zu erfassen (§ 8.2).
[EN] Passes when the final evaluation after 24 months gives a mean of the 8 test vessels of at least 160 stalks per vessel and at the same time at least 80 % of the control vessels'' density (§ 3.7). Enter ''Avg plant density test 24m'' and ''Relative density 24 mon.'' (the control mean is needed for the relative density). Sufficient growth throughout the test is a prerequisite for the verdict ''rhizome resistant'' (§ 3.11); growth is recorded conclusively at the end of the test (§ 8.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-16' AND x.code = 'REQ-18';
UPDATE fields x SET description = 'Bestätigung, dass die Abdichtung nach Entnahme der Vegetationstragschicht fotografisch dokumentiert ist. Ein- und durchgedrungene Rhizome sind beispielhaft fotografisch zu belegen (§ 8.2); die Fotos gehören als Anhang 1 in den Prüfbericht, auch bei einem Befund ohne Ein- oder Durchdringungen (Musterbericht 4.2 „s. Fotos im Anhang 1“).
[EN] Confirm that the liner was photographed after the substrate was removed. Rhizomes that have grown in or through must be documented by example photographs (§ 8.2); the photos go into the report as Annex 1, also when no ingress or penetration was found (model report 4.2 ''see photos in Annex 1'').' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'fotos_dokumentiert';
UPDATE fields x SET description = 'Größte gemessene Eindringtiefe von Rhizomen in den Überlappungsbereich von Nähten, in mm. Bei Eindringungen in Nahtüberlappungen ist die maximale Eindringtiefe festzuhalten (§ 8.2). Nur bei bahnenartigen Abdichtungen mit Nähten relevant; leer lassen, wenn keine Eindringung in eine Überlappung festgestellt wurde. Die Eindringung selbst wird unter „Rhizomeindringungen Nähte“ gezählt.
[EN] Largest measured depth of rhizome ingress into the overlap zone of seams, in mm. For ingress into seam overlaps the maximum depth must be recorded (§ 8.2). Relevant only for sheet-type liners with seams; leave empty if no ingress into an overlap was found. The ingress itself is counted under ''Rhizome ingress seams''.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'max_eindringtiefe_ueberlappung_mm';
UPDATE fields x SET description = 'Anzahl der Rhizome, die durch die Fläche der Abdichtung hindurchgewachsen sind, summiert über alle 8 Prüfgefäße. Rhizomdurchdringungen liegen vor, wenn Rhizome durch die Fläche oder die Nähte durchgewachsen sind (§ 3.10); sie sind in absoluten Zahlen getrennt nach Fläche und Nähten bzw. Arbeitsunterbrechungsfuge zu erfassen (§ 8.2). Jeder Wert > 0 bedeutet „nicht rhizomfest“ (§ 3.11, Tor REQ-20). Erkennbare Durchdringungen sind dem Auftraggeber schon während der Prüfung mitzuteilen (§ 3.12, § 8.1).
[EN] Number of rhizomes that grew through the area of the liner, summed over all 8 test vessels. Penetration means rhizomes have grown through the area or the seams (§ 3.10); they are recorded in absolute numbers, separately for area and seams or work joint (§ 8.2). Any value > 0 means ''not rhizome resistant'' (§ 3.11, gate REQ-20). Visible penetrations must be reported to the client already during the test (§ 3.12, § 8.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rhizomdurchdringung_flaeche_count';
UPDATE fields x SET description = 'Anzahl der Rhizome, die durch Nähte der Abdichtung hindurchgewachsen sind, summiert über alle 8 Prüfgefäße (§ 3.10, § 8.2). Bei bahnenartigen Abdichtungen zählen alle Nähte (Wand-Eck-, Boden-Eck-, T- und Längsnähte nach § 7.1); bei nicht bahnenförmigen Abdichtungen hier die Durchdringungen der Arbeitsunterbrechungsfuge eintragen, falls diese erkennbar ist (§ 8.2). Jeder Wert > 0 bedeutet „nicht rhizomfest“ (§ 3.11, Tor REQ-20).
[EN] Number of rhizomes that grew through seams of the liner, summed over all 8 test vessels (§ 3.10, § 8.2). For sheet-type liners all seams count (wall-corner, floor-corner, T and longitudinal seams per § 7.1); for non-sheet liners enter here the penetrations of the work joint, if it is recognisable (§ 8.2). Any value > 0 means ''not rhizome resistant'' (§ 3.11, gate REQ-20).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rhizomdurchdringung_naehte_count';
UPDATE fields x SET description = 'Anzahl Rhizome, die in bereits vorhandene Poren der Abdichtung (Fläche, Naht oder Arbeitsunterbrechungsfuge) eingewachsen sind, ohne sie zu beschädigen. Solche Fälle gelten nicht als Rhizomeindringung, sind aber im Prüfbericht aufzuführen; für eine eindeutige Bewertung sind die Bereiche unter dem Mikroskop zu betrachten (§ 3.9). Wird von Tor REQ-19 nicht gezählt.
[EN] Number of rhizomes that grew into pre-existing pores of the liner (area, seam or work joint) without damaging it. Such cases do not count as ingress but must be listed in the report; the areas must be examined under the microscope for an unambiguous assessment (§ 3.9). Not counted by gate REQ-19.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rhizome_in_poren_count';
UPDATE fields x SET description = 'Anzahl Rhizome, die höchstens 5 mm in Fläche, Naht oder Arbeitsunterbrechungsfuge eingewachsen sind, bei Produkten mit wachstumshemmenden Wirkstoffen (die hemmende Wirkung entfaltet sich erst nach dem Eindringen). Gilt nicht als Rhizomeindringung, ist aber im Prüfbericht aufzuführen – nur wenn der Hersteller das Produkt zu Prüfungsbeginn als „mit wachstumshemmenden Wirkstoffen versehen“ definiert hat (§ 3.9; Herstellerangaben nach § 6). Tiefer eingewachsene Rhizome zählen als Eindringung.
[EN] Number of rhizomes grown at most 5 mm into area, seam or work joint of products with growth-inhibiting agents (the inhibiting effect only unfolds after ingress). Does not count as ingress but must be listed in the report – only if the manufacturer declared the product ''provided with growth-inhibiting agents'' at the start of the test (§ 3.9; manufacturer data per § 6). Rhizomes grown in deeper count as ingress.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rhizome_unter_5mm_bei_hemmstoff_count';
UPDATE fields x SET description = 'Anzahl gewerteter Rhizomeindringungen in die Arbeitsunterbrechungsfuge, summiert über alle 8 Prüfgefäße. Gilt für nicht bahnenförmige Abdichtungen (Flüssigabdichtung, Gussasphalt, GUP), die in zwei Arbeitsschritten mit durchgehender Arbeitsunterbrechungsfuge in Gefäßmitte eingebaut wurden (§ 7.1); erfasst wird die Fuge, falls sie erkennbar ist (§ 8.2). Eindringung = aktiv geschaffener Hohlraum mit beschädigter Abdichtungsschicht (§ 3.9). Bei bahnenartigen Abdichtungen 0 eintragen; Tor REQ-19 verlangt 0.
[EN] Number of counted rhizome ingresses into the work joint, summed over all 8 test vessels. Applies to non-sheet liners (liquid-applied, mastic asphalt, GRP) installed in two steps with a continuous work joint across the middle of the vessel (§ 7.1); the joint is recorded if it is recognisable (§ 8.2). Ingress = actively created cavity with damaged sealing layer (§ 3.9). Enter 0 for sheet-type liners; gate REQ-19 requires 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rhizomeindringung_arbeitsfuge_count';
UPDATE fields x SET description = 'Anzahl gewerteter Rhizomeindringungen in die Fläche der Abdichtung, summiert über alle 8 Prüfgefäße. Eine Eindringung liegt vor, wenn Rhizome eingewachsen sind und dabei aktiv Hohlräume geschaffen und die Abdichtungsschicht beschädigt haben (§ 3.9); Erfassung in absoluten Zahlen zum Ende der Prüfung (§ 8.2). Nicht zu werten (aber zu berichten): Rhizome in vorhandenen Poren, ≤ 5 mm bei Hemmstoff-Produkten, in nicht schützende Schichten mehrschichtiger Produkte, in zusätzliche Nahtversiegelungen (§ 3.9). Tor REQ-19 verlangt 0.
[EN] Number of counted rhizome ingresses into the area of the liner, summed over all 8 test vessels. Ingress exists when rhizomes have grown in, actively creating cavities and damaging the sealing layer (§ 3.9); recorded in absolute numbers at the end of the test (§ 8.2). Not counted (but reported): rhizomes in pre-existing pores, ≤ 5 mm in products with inhibitors, in non-protective layers of multilayer products, in additional seam sealing (§ 3.9). Gate REQ-19 requires 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rhizomeindringung_flaeche_count';
UPDATE fields x SET description = 'Anzahl gewerteter Rhizomeindringungen in die Nähte bahnenartiger Abdichtungen, summiert über alle 8 Prüfgefäße (§ 3.9, § 8.2). Geprüft werden die am Untersuchungsort gefügten Nähte: vier Wand-Eck-Nähte, zwei Boden-Eck-Nähte und T-Naht des ersten sowie zwei Längsnähte des zweiten Prüfmusters (§ 7.1). Rhizome in zusätzlichen Nahtversiegelungen ohne Beschädigung der Nahtverbindung zählen nicht (§ 3.9). Bei nicht bahnenförmigen Abdichtungen 0 eintragen; Tor REQ-19 verlangt 0.
[EN] Number of counted rhizome ingresses into the seams of sheet-type liners, summed over all 8 test vessels (§ 3.9, § 8.2). Examined are the seams joined on site: four wall-corner seams, two floor-corner seams and the T-seam of the first sample plus two longitudinal seams of the second sample (§ 7.1). Rhizomes in additional seam sealing without damage to the seam do not count (§ 3.9). Enter 0 for non-sheet liners; gate REQ-19 requires 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rhizomeindringung_naehte_count';
UPDATE fields x SET description = 'Bestätigung, dass das Prüfinstitut von der Abdichtung Rückstellproben genommen hat – vor der Untersuchung (§ 6) und zum Ende der Prüfung, die das Ergebnis dokumentieren (§ 8.2). Die Proben werden beim Prüfinstitut gelagert (§ 4); der Prüfbericht muss den Satz „Rückstellproben der untersuchten Produkte werden beim Prüfinstitut gelagert“ enthalten (§ 9). Entnahme und Lagerung sind Aufgabe des Prüfinstituts (§ 11).
[EN] Confirm that the test institute took retained samples of the liner – before the test (§ 6) and at the end of the test, documenting the result (§ 8.2). Samples are stored at the institute (§ 4); the report must contain the sentence that retained samples are stored at the test institute (§ 9). Taking and storing them is the institute''s duty (§ 11).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rueckstellproben_entnommen';
UPDATE fields x SET description = 'Datum, an dem die Rückstellprobe vor der Untersuchung entnommen wurde. Vom Prüfinstitut ist vor und nach der Untersuchung eine Rückstellprobe zu nehmen (§ 6); sie belegt den Ausgangszustand des gelieferten Produkts. Lagerbedingungen und Mindestgröße siehe die folgenden Felder.
[EN] Date on which the retained sample was taken before the test. The institute must take a retained sample before and after the test (§ 6); this one documents the initial condition of the delivered product. Storage conditions and minimum size: see the following fields.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rueckstellprobe_vor_pruefung_datum';
UPDATE fields x SET description = 'Datum, an dem die Rückstellprobe nach der Untersuchung entnommen wurde. Zum Ende der Prüfung sind von der untersuchten Abdichtung Rückstellproben zu entnehmen, die das Ergebnis dokumentieren, und nach § 6 zu lagern (§ 8.2). Liegt in der Regel am Tag der Endauswertung (Blatt 16).
[EN] Date on which the retained sample was taken after the test. At the end of the test retained samples documenting the result must be taken from the examined liner and stored per § 6 (§ 8.2). Usually the day of the final evaluation (sheet 16).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rueckstellprobe_nach_pruefung_datum';
UPDATE fields x SET description = 'Fläche des als Rückstellprobe entnommenen Teilstücks in m². Das Teilstück muss eine Fläche von mindestens 0,5 m² aufweisen (§ 6); Tor REQ-23 verlangt ≥ 0,5. Wert aus der Entnahmeniederschrift des Prüfinstituts.
[EN] Area of the piece taken as retained sample in m². The piece must have an area of at least 0.5 m² (§ 6); gate REQ-23 requires ≥ 0.5. Value from the institute''s sampling record.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rueckstellprobe_flaeche_m2';
UPDATE fields x SET description = 'Bestätigung, dass das entnommene Teilstück zumindest eine Nahtstelle pro angewandter Fügetechnik bzw. – bei nicht bahnenförmigen Abdichtungen – eine Arbeitsunterbrechungsfuge enthält (§ 6). Welche Fügetechniken angewandt wurden, steht in den Herstellerangaben (§ 6, Blatt 02). Tor REQ-23 verlangt den Haken.
[EN] Confirm that the piece taken contains at least one seam per joining technique used or – for non-sheet liners – a work joint (§ 6). The joining techniques used are listed in the manufacturer data (§ 6, sheet 02). Gate REQ-23 requires the tick.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rueckstellprobe_enthaelt_naht_je_fuegetechnik';
UPDATE fields x SET description = 'Niedrigste Temperatur am Lagerort der Rückstellprobe in °C. Die Rückstellprobe ist bei Temperaturen über 5 °C zu lagern (§ 6); Tor REQ-23 verlangt einen Wert > 5, genau 5 °C genügt nicht. Wert aus der Temperaturüberwachung des Lagerraums.
[EN] Lowest temperature at the storage place of the retained sample in °C. The sample must be stored at temperatures above 5 °C (§ 6); gate REQ-23 requires a value > 5, exactly 5 °C does not pass. Value from the storage room''s temperature monitoring.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rueckstellprobe_lager_temp_min_C';
UPDATE fields x SET description = 'Höchste Temperatur am Lagerort der Rückstellprobe in °C. Die Rückstellprobe ist bei Temperaturen unter 25 °C zu lagern (§ 6); Tor REQ-23 verlangt einen Wert < 25, genau 25 °C genügt nicht.
[EN] Highest temperature at the storage place of the retained sample in °C. The sample must be stored at temperatures below 25 °C (§ 6); gate REQ-23 requires a value < 25, exactly 25 °C does not pass.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rueckstellprobe_lager_temp_max_C';
UPDATE fields x SET description = 'Bestätigung, dass die Rückstellprobe trocken und dunkel beim Prüfinstitut gelagert wird (§ 6). Tor REQ-23 verlangt den Haken; zusammen mit den Temperaturfeldern bildet er die Lagerbedingungen des § 6 ab.
[EN] Confirm that the retained sample is stored dry and dark at the test institute (§ 6). Gate REQ-23 requires the tick; together with the temperature fields it covers the storage conditions of § 6.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rueckstellprobe_trocken_dunkel';
UPDATE fields x SET description = 'Datum, bis zu dem die Lagerung der Rückstellprobe mindestens zugesagt ist. Die Dauer der Lagerung muss mindestens der Gültigkeitsdauer des Prüfberichts entsprechen (§ 6) – grundsätzlich 10 Jahre ab Berichtsdatum, bei Verlängerung in 5-Jahres-Schritten entsprechend länger (§ 9). Das Datum darf nicht vor „Bescheinigung gültig bis“ (Blatt 21) liegen; ein automatischer Vergleich findet nicht statt.
[EN] Date until which storage of the retained sample is committed at least. The storage period must be at least the validity period of the test report (§ 6) – 10 years from the report date in principle, correspondingly longer when extended in 5-year steps (§ 9). The date must not be earlier than ''Certificate valid until'' (sheet 21); there is no automatic comparison.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'rueckstellprobe_lagerung_bis';
UPDATE fields x SET description = 'Bestätigung, dass stoffliche Unverträglichkeiten bei der Lagerung der Rückstellprobe beachtet wurden (§ 6) – also kein Kontakt mit Materialien, die das Produkt verändern könnten. Reine Bestätigung ohne Tor.
[EN] Confirm that material incompatibilities were observed when storing the retained sample (§ 6) – i.e. no contact with materials that could alter the product. Attestation only, no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.symbol = 'lagerung_unvertraeglichkeiten_beachtet';
UPDATE compliance_requirements x SET description = 'Besteht nur, wenn in allen 8 Prüfgefäßen keine gewertete Rhizomeindringung festgestellt wurde: Fläche = 0, Nähte = 0 und Arbeitsunterbrechungsfuge = 0. Alle drei Zählfelder müssen eingetragen sein (für nicht vorhandene Bereiche 0). Eine Eindringung liegt vor, wenn Rhizome aktiv Hohlräume geschaffen und die Abdichtungsschicht beschädigt haben; Rhizome in vorhandenen Poren, ≤ 5 mm bei Hemmstoff-Produkten, in nicht schützenden Schichten oder in Nahtversiegelungen zählen nicht, sind aber zu berichten (§ 3.9). Ohne Eindringungen – und ohne Durchdringungen (REQ-20) – gilt das Produkt als rhizomfest (§ 3.11); Erfassung in absoluten Zahlen zum Ende der Prüfung (§ 8.2).
[EN] Passes only when no counted rhizome ingress was found in any of the 8 test vessels: area = 0, seams = 0 and work joint = 0. All three count fields must be entered (0 for areas that do not exist). Ingress exists when rhizomes have actively created cavities and damaged the sealing layer; rhizomes in pre-existing pores, ≤ 5 mm in inhibitor products, in non-protective layers or in seam sealing do not count but must be reported (§ 3.9). Without ingress – and without penetration (REQ-20) – the product counts as rhizome resistant (§ 3.11); recorded in absolute numbers at the end of the test (§ 8.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.code = 'REQ-19';
UPDATE compliance_requirements x SET description = 'Besteht nur, wenn in allen 8 Prüfgefäßen keine Rhizomdurchdringung festgestellt wurde: Fläche = 0 und Nähte (bzw. Arbeitsunterbrechungsfuge) = 0; beide Zählfelder müssen eingetragen sein. Eine Durchdringung liegt vor, wenn Rhizome durch die Fläche oder die Nähte durchgewachsen sind (§ 3.10). Ein Produkt gilt nur als rhizomfest, wenn nach Ablauf der Prüfdauer keine Durchdringungen und keine Eindringungen vorliegen (§ 3.11); Erfassung getrennt nach Bereichen zum Prüfende (§ 8.2).
[EN] Passes only when no rhizome penetration was found in any of the 8 test vessels: area = 0 and seams (or work joint) = 0; both count fields must be entered. Penetration exists when rhizomes have grown through the area or the seams (§ 3.10). A product counts as rhizome resistant only if, at the end of the test period, there are no penetrations and no ingresses (§ 3.11); recorded separately per zone at the end of the test (§ 8.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.code = 'REQ-20';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die Rückstellprobe den Anforderungen des § 6 entspricht: Fläche des Teilstücks mindestens 0,5 m², mindestens eine Nahtstelle je Fügetechnik bzw. eine Arbeitsunterbrechungsfuge enthalten, Lagerung bei Temperaturen über 5 °C und unter 25 °C, trocken und dunkel beim Prüfinstitut. Dafür Fläche, niedrigste und höchste Lagertemperatur eintragen und beide Bestätigungen setzen. Die Lagerdauer muss mindestens der Gültigkeitsdauer des Prüfberichts entsprechen (§ 6) – sie wird nur als Datum erfasst, nicht geprüft.
[EN] Passes when the retained sample meets § 6: area of the piece at least 0.5 m², at least one seam per joining technique or a work joint included, storage at temperatures above 5 °C and below 25 °C, dry and dark at the test institute. Enter the area, the lowest and highest storage temperature and set both attestations. The storage period must be at least the validity of the test report (§ 6) – it is recorded as a date only, not checked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-17' AND x.code = 'REQ-23';
UPDATE fields x SET description = 'Nur ausfüllen, wenn das Prüfergebnis „vorzeitig abgebrochen“ lautet. Die Prüfbestimmungen kennen zwei Fälle: erkennbare Durchdringungen von Rhizomen am Produkt – der Auftraggeber ist zu unterrichten, die Prüfung kann abgebrochen werden – und keine ausreichende Wuchsleistung der Testpflanzen – die Prüfung ist abzubrechen (§ 3.12, § 8.1). Fall, Zeitpunkt und Befund kurz angeben; der Text geht in die schriftliche Mitteilung mit begründeter Feststellung, die statt eines Prüfberichts ergeht (§ 9).
[EN] Fill in only if the verdict is ''terminated early''. The test rules know two cases: visible rhizome penetrations of the product – the client must be informed and the test may be aborted – and insufficient growth of the test plants – the test must be aborted (§ 3.12, § 8.1). State case, date and finding briefly; the text goes into the written notice with reasoned finding that is issued instead of a test report (§ 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-18' AND x.symbol = 'abbruchsgrund';
UPDATE fields x SET description = 'Gesamtergebnis der Prüfung nach § 3.11. „rhizomfest“ nur, wenn in allen Prüfgefäßen nach Ablauf der Prüfdauer keine Rhizomeindringungen (§ 3.9) und keine Rhizomdurchdringungen (§ 3.10) festzustellen sind und die Pflanzen im gesamten Prüfungsverlauf eine ausreichende Wuchsleistung (§ 3.7) erbracht haben; daraus folgt auch die Wurzelfestigkeit. „nicht rhizomfest“ bei Ein- oder Durchdringungen; „vorzeitig abgebrochen“ bei Abbruch nach § 3.12. Nur bei „rhizomfest“ wird ein Prüfbericht erstellt, sonst eine schriftliche Mitteilung (§ 9).
[EN] Overall result per § 3.11. ''rhizome resistant'' only if in all test vessels at the end of the test period no rhizome ingress (§ 3.9) and no penetration (§ 3.10) is found and the plants showed sufficient growth throughout (§ 3.7); root resistance follows from this. ''not rhizome resistant'' with ingress or penetration; ''terminated early'' if aborted per § 3.12. A test report is issued only for ''rhizome resistant'', otherwise a written notice (§ 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-18' AND x.symbol = 'pruefergebnis_rhizomfest';
UPDATE compliance_requirements x SET description = 'Besteht nur mit dem Ergebnis „rhizomfest“. Voraussetzung dafür nach § 3.11: null gewertete Eindringungen und null Durchdringungen in allen 8 Prüfgefäßen (Blatt 17, REQ-19/REQ-20) sowie bestandene Wuchsleistung an allen vier Terminen (REQ-15 bis REQ-18). Das Feld „Prüfergebnis Rhizomfestigkeit“ muss gesetzt sein. Ein Produkt mit „nicht rhizomfest“ oder „vorzeitig abgebrochen“ erhält keinen Prüfbericht, sondern nur eine schriftliche Mitteilung mit begründeter Feststellung (§ 9).
[EN] Passes only with the verdict ''rhizome resistant''. Prerequisites per § 3.11: zero counted ingresses and zero penetrations in all 8 test vessels (sheet 17, REQ-19/REQ-20) and passed growth at all four dates (REQ-15 to REQ-18). The field ''Verdict rhizome resistance'' must be set. A product with ''not rhizome resistant'' or ''terminated early'' receives no test report, only a written notice with reasoned finding (§ 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-18' AND x.code = 'REQ-RHZ18-VERDICT';
UPDATE fields x SET description = 'Bestätigung, dass der Prüfbericht alle Pflichtinhalte des § 9 enthält: Herstellerangaben zum Produkt (§ 6), detaillierte Angaben zur Vorbereitung der Prüfgefäße (§ 7) oder Hinweis auf das FLL-Verfahren mit Ausgabedatum im Anhang, alle Auswertungsergebnisse (§ 8) und eine zusammenfassende Bewertung nach § 3.11 – sowie die vier Pflichtformulierungen: Seitenzahl und „nur in ungekürzter Form“, Bindung an Kenndaten und Fügetechnik ohne Übertragung auf andere Produkte, Lagerung der Rückstellproben beim Prüfinstitut, Erstellungsdatum mit 10 Jahren Gültigkeit. Bericht in doppelter Ausführung (Prüfinstitut und Auftraggeber); ein Musterprüfbericht ist beigefügt (S. 25–31).
[EN] Confirm that the test report contains all mandatory contents of § 9: manufacturer data on the product (§ 6), detailed data on the preparation of the test vessels (§ 7) or a reference to the FLL procedure with edition date in the annex, all evaluation results (§ 8) and a summary assessment per § 3.11 – plus the four mandatory wordings: page count and ''only in unabridged form'', results bound to product data and joining technique with no transfer to other products, retained samples stored at the institute, report date with 10-year validity. Two copies (institute and client); a model report is attached (pp. 25–31).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-19' AND x.symbol = 'attest_flltp_rhz_19_req_21';
UPDATE fields x SET description = 'Erstellungsdatum des Prüfberichts, wie es in der Pflichtformulierung „Der Prüfbericht wurde am … erstellt und hat grundsätzlich eine Gültigkeitsdauer von 10 Jahren“ steht (§ 9; Deckblatt des Musterberichts „Datum des Berichts“). Beginn der Gültigkeitsdauer; „Bescheinigung gültig bis“ auf Blatt 21 wird nicht automatisch abgeleitet, sondern aus diesem Datum und der Gültigkeitsdauer (Jahre) gebildet und eingetragen. Erst nach Beendigung des Versuchs – Zwischenergebnisse dürfen nicht schriftlich bekannt gegeben werden (§ 9).
[EN] Date of issue of the test report as stated in the mandatory wording ''The test report was prepared on … and is valid in principle for 10 years'' (§ 9; model report cover ''Datum des Berichts''). Start of the validity period; ''Certificate valid until'' on sheet 21 is not derived automatically but formed from this date and the validity period (years) and entered. Only after the test is finished – interim results may not be issued in writing (§ 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-19' AND x.symbol = 'bericht_datum';
UPDATE fields x SET description = 'Gesamtzahl der Seiten des fertigen Berichts einschließlich Anhängen (Fotos, Daten zur Pflanzenentwicklung, Verfahrensbeschreibung). Pflichtformulierung: „Der Prüfbericht umfasst … Seiten und darf nur in ungekürzter Form verwendet werden“ (§ 9); im Musterbericht steht die Seitenzahl auf dem Deckblatt und in der Kopfzeile jeder Seite.
[EN] Total number of pages of the finished report including annexes (photos, plant-development data, description of the procedure). Mandatory wording: ''The test report comprises … pages and may only be used in unabridged form'' (§ 9); in the model report the page count appears on the cover and in the header of every page.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-19' AND x.symbol = 'bericht_seitenanzahl';
UPDATE fields x SET description = 'Gültigkeitsdauer des Prüfberichts in Jahren. Der Bericht hat grundsätzlich eine Gültigkeitsdauer von 10 Jahren (§ 9; Musterbericht „Gültigkeitsdauer von 10 Jahren“) – bei Erstausstellung 10 eintragen; Tor REQ-24 warnt bei einem anderen Wert. Eine Verlängerung in Zeitabschnitten von 5 Jahren wird in Blatt 20 behandelt. Die Rückstellproben sind mindestens so lange zu lagern (§ 6).
[EN] Validity period of the test report in years. The report is valid in principle for 10 years (§ 9; model report ''validity of 10 years'') – enter 10 for a first issue; gate REQ-24 warns on any other value. Extension in 5-year steps is handled in sheet 20. Retained samples must be stored at least as long (§ 6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-19' AND x.symbol = 'gueltigkeitsdauer_jahre';
UPDATE compliance_requirements x SET description = 'Besteht, wenn die Bestätigung „Nachweis: § 9“ gesetzt ist. Das setzt voraus, dass der Bericht die vier Pflichtinhalte (Herstellerangaben, Vorbereitung der Prüfgefäße, alle Auswertungsergebnisse, zusammenfassende Bewertung) und die vier Pflichtformulierungen (Seitenzahl/ungekürzte Form, Bindung an Kenndaten und Fügetechnik ohne Übertragung, Rückstellproben beim Prüfinstitut, Erstellungsdatum mit 10 Jahren Gültigkeit) enthält und in doppelter Ausführung erstellt ist (§ 9). Ein Prüfbericht wird nur erstellt, wenn sich das Produkt nach § 3.11 als rhizomfest erwiesen hat.
[EN] Passes when the attestation ''Nachweis: § 9'' is ticked. That presupposes the report contains the four mandatory contents (manufacturer data, preparation of the test vessels, all evaluation results, summary assessment) and the four mandatory wordings (page count/unabridged form, binding to product data and joining technique without transfer, retained samples at the institute, report date with 10-year validity) and is issued in two copies (§ 9). A test report is issued only if the product proved rhizome resistant per § 3.11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-19' AND x.code = 'REQ-21';
UPDATE compliance_requirements x SET description = 'Warnung (kein Sperren), wenn die Gültigkeitsdauer nicht 10 Jahre beträgt. Der Prüfbericht hat grundsätzlich eine Gültigkeitsdauer von 10 Jahren (§ 9); „grundsätzlich“ lässt Ausnahmen zu, daher nur eine Warnung. Zum Bestehen 10 eintragen; Verlängerungen um je 5 Jahre werden in Blatt 20 unter den Bedingungen des § 9 erfasst, nicht hier.
[EN] Warning (no block) when the validity period is not 10 years. The test report is valid in principle for 10 years (§ 9); ''in principle'' allows exceptions, hence only a warning. Enter 10 to pass; extensions by 5 years each are recorded in sheet 20 under the conditions of § 9, not here.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-19' AND x.code = 'REQ-24';
UPDATE fields x SET description = 'Nur bei beantragter Verlängerung. Bestätigung, dass der Hersteller durch eidesstattliche Erklärung zusichert, dass das Produkt sowie dessen Herstellung und Fügetechnik mit dem geprüften Produkt identisch sind (§ 9, vierte Bedingung). Die Erklärung liegt dem Prüfinstitut vor; Tor REQ-22 verlangt den Haken.
[EN] Only when an extension is applied for. Confirm that the manufacturer certifies by affidavit that the product, its manufacture and its joining technique are identical to the tested product (§ 9, fourth condition). The affidavit is on file at the test institute; gate REQ-22 requires the tick.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-20' AND x.symbol = 'eidesstattliche_erklaerung_vorhanden';
UPDATE fields x SET description = 'Nur bei beantragter Verlängerung. Bestätigung, dass das geprüfte Produkt noch dem aktuellen Lieferprogramm des Antragstellers entspricht (§ 9, zweite Bedingung). Ein umbenanntes oder ersetztes Produkt gilt nicht als dasselbe; eine Neuausstellung ohne erneute Prüfung ist dafür nicht zulässig (§ 10). Tor REQ-22 verlangt den Haken.
[EN] Only when an extension is applied for. Confirm that the tested product is still part of the applicant''s current product range (§ 9, second condition). A renamed or replaced product does not count as the same; reissuing without retesting is not permitted for it (§ 10). Gate REQ-22 requires the tick.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-20' AND x.symbol = 'produkt_aktuell_im_lieferprogramm';
UPDATE fields x SET description = 'Nur bei beantragter Verlängerung. Bestätigung, dass die Prüfgrundlagen – diese Prüfbestimmungen und das zugrunde gelegte Verfahren – seit der Erstprüfung in wesentlichen Punkten nicht geändert wurden (§ 9, erste Bedingung). Tor REQ-22 verlangt den Haken.
[EN] Only when an extension is applied for. Confirm that the test basis – these test rules and the procedure applied – has not changed in essential points since the original test (§ 9, first condition). Gate REQ-22 requires the tick.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-20' AND x.symbol = 'pruefgrundlagen_unveraendert';
UPDATE fields x SET description = 'Nur bei beantragter Verlängerung. Bestätigung, dass erneut Rückstellmuster beim Prüfinstitut hinterlegt wurden (§ 9, dritte Bedingung) – mit Fläche ≥ 0,5 m², Naht je Fügetechnik und Lagerung über 5 °C und unter 25 °C, trocken und dunkel, mindestens für die verlängerte Gültigkeitsdauer (§ 6). Tor REQ-22 verlangt den Haken.
[EN] Only when an extension is applied for. Confirm that new retained samples have been deposited at the test institute (§ 9, third condition) – with area ≥ 0.5 m², a seam per joining technique and storage above 5 °C and below 25 °C, dry and dark, at least for the extended validity (§ 6). Gate REQ-22 requires the tick.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-20' AND x.symbol = 'rueckstellmuster_erneut_hinterlegt';
UPDATE fields x SET description = 'Nur bei beantragter Verlängerung. Länge des Verlängerungszeitraums in Jahren: Die Gültigkeitsdauer kann durch Bestätigung des Prüfinstituts in Zeitabschnitten von 5 Jahren verlängert werden (§ 9). 5 eintragen; Tor REQ-22 verlangt genau 5.
[EN] Only when an extension is applied for. Length of the extension period in years: the validity can be extended by confirmation of the test institute in periods of 5 years (§ 9). Enter 5; gate REQ-22 requires exactly 5.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-20' AND x.symbol = 'verlangerung_zeitabschnitt_jahre';
UPDATE fields x SET description = 'Ankreuzen, wenn nicht ein neuer Prüfbericht, sondern die Verlängerung der Gültigkeitsdauer eines bestehenden Berichts beantragt wird (§ 9: Verlängerung „jedoch nur wenn“ vier Bedingungen erfüllt sind). Mit dem Haken erscheinen die vier Bedingungen und der Zeitabschnitt, und Tor REQ-22 wird scharf; ohne Haken (Erstausstellung) bleibt das Blatt ohne Prüfung. Reine Neuausstellung eines Berichts ist nur zur Fehlerkorrektur oder Ergänzung ausgelassener, damals verfügbarer Daten zulässig (§ 10).
[EN] Tick when not a new test report but an extension of the validity of an existing report is applied for (§ 9: extension ''but only if'' four conditions are met). With the tick the four conditions and the period appear and gate REQ-22 is armed; without it (first issue) the sheet has no check. Reissuing a report is allowed only to correct errors or add omitted data that were available at the time (§ 10).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-20' AND x.symbol = 'verlaengerung_beantragt';
UPDATE compliance_requirements x SET description = 'Gilt nur, wenn „Verlängerung beantragt“ angekreuzt ist; bei Erstausstellung ist das Tor ohne Wirkung. Dann besteht es nur, wenn alle vier Bedingungen des § 9 bestätigt sind – Prüfgrundlagen in wesentlichen Punkten unverändert, Produkt noch im aktuellen Lieferprogramm, erneut Rückstellmuster hinterlegt, eidesstattliche Erklärung des Herstellers zur Identität von Produkt, Herstellung und Fügetechnik – und der Zeitabschnitt 5 Jahre beträgt. Alle vier Haken und der Wert 5 sind einzutragen; die Verlängerung erfolgt durch Bestätigung des Prüfinstituts (§ 9).
[EN] Applies only when ''Extension applied for'' is ticked; for a first issue the gate has no effect. It then passes only if all four conditions of § 9 are confirmed – test basis unchanged in essential points, product still in the current range, new retained samples deposited, manufacturer''s affidavit on the identity of product, manufacture and joining technique – and the period is 5 years. Enter all four ticks and the value 5; the extension is granted by confirmation of the test institute (§ 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-20' AND x.code = 'REQ-22';
UPDATE fields x SET description = 'Endgültiges Ergebnis für die Gesamtbescheinigung, identisch mit dem Prüfergebnis aus Blatt 18. „rhizomfest“ nur bei null Ein- und Durchdringungen in allen Prüfgefäßen und ausreichender Wuchsleistung im gesamten Verlauf (§ 3.11); das Produkt gilt dann auch als wurzelfest (§ 3.11; Musterbericht Abschnitt 5). „nicht rhizomfest“ und „vorzeitig abgebrochen“ führen zu einer schriftlichen Mitteilung statt eines Berichts (§ 9). Hinweis des Musterberichts: Bei Bambus in Gewässernähe sind über den Rhizomschutz hinausgehende Schutzmaßnahmen erforderlich.
[EN] Final result for the overall certificate, identical to the verdict in sheet 18. ''rhizome resistant'' only with zero ingress and penetration in all test vessels and sufficient growth throughout (§ 3.11); the product then also counts as root resistant (§ 3.11; model report section 5). ''not rhizome resistant'' and ''terminated early'' lead to a written notice instead of a report (§ 9). Note from the model report: for bamboo near water, protective measures beyond this rhizome protection are required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-21' AND x.symbol = 'final_rhizom_conformity';
UPDATE fields x SET description = 'Ende der Gültigkeit des Prüfberichts: Berichtsdatum (Blatt 19) plus Gültigkeitsdauer – grundsätzlich 10 Jahre (§ 9; Musterbericht „Gültigkeitsdauer von 10 Jahren“); bei bestätigter Verlängerung (Blatt 20) jeweils 5 Jahre später. Die Rückstellproben müssen mindestens bis zu diesem Datum gelagert werden (§ 6) – mit „Rückstellprobe – Lagerung mindestens bis“ (Blatt 17) abgleichen.
[EN] End of validity of the test report: report date (sheet 19) plus validity period – 10 years in principle (§ 9; model report ''validity of 10 years''); with a confirmed extension (sheet 20) 5 years later each time. Retained samples must be stored at least until this date (§ 6) – reconcile with ''Retained sample – stored at least until'' (sheet 17).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-21' AND x.symbol = 'bescheinigung_gueltig_bis';
UPDATE fields x SET description = 'Name des Prüfinstituts, das die Prüfung durchgeführt hat und den Bericht ausstellt. Der vollständige Prüfbericht ist von der jeweiligen Prüfinstitution in doppelter Ausführung zu erstellen (§ 9); das Erstellen des Prüfberichts gehört zu den Leistungen des Prüfinstituts (§ 11). Steht auf dem Deckblatt und in der Kopfzeile jeder Seite des Musterberichts.
[EN] Name of the test institute that ran the test and issues the report. The complete test report is prepared by the respective test institution in two copies (§ 9); preparing the report is one of the institute''s duties (§ 11). Appears on the cover and in the header of every page of the model report.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-21' AND x.symbol = 'bescheinigung_ausgestellt_durch';
UPDATE fields x SET description = 'Berichtsnummer des Prüfinstituts („Ber.-Nr.“ in der Kopfzeile jeder Seite des Musterberichts). Sie identifiziert den Bericht eindeutig – nötig für die eindeutige Bezugnahme auf den Erstbericht bei Neuausstellung oder Verlängerung (§ 10) und für die Zuordnung der Rückstellproben.
[EN] Report number of the test institute (''Ber.-Nr.'' in the header of every page of the model report). It identifies the report unambiguously – needed for unambiguous reference to the original report on reissue or extension (§ 10) and for assigning the retained samples.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-21' AND x.symbol = 'bescheinigung_pruefnummer';
UPDATE fields x SET description = 'Datum der Ausstellung und Unterzeichnung des Berichts (Musterbericht Abschnitt 5: „Datum“ neben Name und Unterschrift des Bearbeiters). In der Regel gleich dem Berichtsdatum aus Blatt 19, mit dem die 10-jährige Gültigkeit beginnt (§ 9). Erst nach Beendigung des Versuchs.
[EN] Date of issue and signing of the report (model report section 5: ''Datum'' next to name and signature of the author). Normally equal to the report date in sheet 19, which starts the 10-year validity (§ 9). Only after the test has ended.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-21' AND x.symbol = 'bescheinigung_ausstellung_datum';
UPDATE fields x SET description = 'Bestätigung, dass der Bericht vom verantwortlichen Bearbeiter des Prüfinstituts mit Name, Unterschrift und Kontaktdaten gezeichnet ist (Musterbericht Abschnitt 5). Der Bericht ist in doppelter Ausführung – je ein Exemplar für Prüfinstitut und Auftraggeber – zu erstellen und darf nur in ungekürzter Form verwendet werden (§ 9).
[EN] Confirm that the report is signed by the responsible author of the test institute with name, signature and contact details (model report section 5). The report is issued in two copies – one each for the institute and the client – and may only be used in unabridged form (§ 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-21' AND x.symbol = 'pruefer_signatur_eingeholt';
UPDATE compliance_requirements x SET description = 'Besteht nur, wenn die endgültige Konformität „rhizomfest“ lautet; das Feld muss gesetzt sein und dem Prüfergebnis aus Blatt 18 entsprechen. Nach § 3.11 ist ein Produkt rhizomfest, wenn in allen Prüfgefäßen keine Rhizomein- und -durchdringungen vorliegen und die Wuchsleistung ausreichend war. Nur dann wird ein Prüfbericht ausgestellt; Firmen und Produkte, die ohne Erfolg teilgenommen haben, erhalten lediglich eine schriftliche Mitteilung mit begründeter Feststellung (§ 9).
[EN] Passes only when the final conformity is ''rhizome resistant''; the field must be set and match the verdict in sheet 18. Per § 3.11 a product is rhizome resistant when no rhizome ingress or penetration is found in any test vessel and growth was sufficient. Only then is a test report issued; companies and products that took part without success receive merely a written notice with reasoned finding (§ 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-TP-RHIZOM-2023' AND w.code = 'FLLTP-RHZ-21' AND x.code = 'REQ-RHZ21-CONFORMITY';
COMMIT;
